(()=> {
  const STORAGE='bjtMockExamV1';
  const PART_LIMITS={1:45*60,2:30*60,3:30*60};
  const EXAMS={"BJT-MOCK-01":{"id":"BJT-MOCK-01","code":"MOCK 01","title":"模擬試驗 第1回","questions":[{"id":"M01-P1-S1-Q01","part":1,"section":1,"type":"listening_scene","prompt":"","options":["女の人が契約書に署名しています。","女の人が荷物を受け取っています。","女の人が資料をコピーしています。","女の人が名刺を整理しています。"],"answer":2,"b":-1.1,"explanation":"畫面是女性從配送人員手中接過包裹，因此②最符合。","audioText":"1、女の人が契約書に署名しています。2、女の人が荷物を受け取っています。3、女の人が資料をコピーしています。4、女の人が名刺を整理しています。","visual":{"kind":"emoji","scene":"📦  →  👩‍💼","sub":"🚚　　🏢"}},{"id":"M01-P1-S1-Q02","part":1,"section":1,"type":"listening_scene","prompt":"","options":["男の人が売上データを説明しています。","男の人が採用面接をしています。","男の人が入場券を販売しています。","男の人が倉庫の在庫を数えています。"],"answer":1,"b":-0.9,"explanation":"投影されたグラフを指しながら説明している場面なので①。","audioText":"1、男の人が売上データを説明しています。2、男の人が採用面接をしています。3、男の人が入場券を販売しています。4、男の人が倉庫の在庫を数えています。","visual":{"kind":"emoji","scene":"🧑‍💼 👉 📊","sub":"👥　会議室"}},{"id":"M01-P1-S1-Q03","part":1,"section":1,"type":"listening_scene","prompt":"","options":["受付の人がお客様を見送っています。","受付の人がお客様から代金を受け取っています。","受付の人がお客様を応接室へ案内しています。","受付の人が机を移動しています。"],"answer":3,"b":-0.8,"explanation":"受付担当者が来客をソファのある応接スペースへ案内する場面なので③。","audioText":"1、受付の人がお客様を見送っています。2、受付の人がお客様から代金を受け取っています。3、受付の人がお客様を応接室へ案内しています。4、受付の人が机を移動しています。","visual":{"kind":"emoji","scene":"👩‍💼 ➡️ 🛋️ 👨‍💼","sub":"受付　　応接室"}},{"id":"M01-P1-S1-Q04","part":1,"section":1,"type":"listening_scene","prompt":"","options":["社員がロッカーから書類を出しています。","社員が入館証を返却しています。","社員がコピー機を操作しています。","社員がタイムカードを押しています。"],"answer":4,"b":-1.0,"explanation":"出入口付近でカードを打刻しているため④。","audioText":"1、社員がロッカーから書類を出しています。2、社員が入館証を返却しています。3、社員がコピー機を操作しています。4、社員がタイムカードを押しています。","visual":{"kind":"emoji","scene":"🧑‍💼 🪪➡️⏱️","sub":"🏢 出入口"}},{"id":"M01-P1-S1-Q05","part":1,"section":1,"type":"listening_scene","prompt":"","options":["二人が商品の棚卸しをしています。","二人が商談を終えて握手をしています。","二人が名札を交換しています。","二人が会議資料を廃棄しています。"],"answer":2,"b":-0.7,"explanation":"商談テーブルの横で双方が握手しているため②。","audioText":"1、二人が商品の棚卸しをしています。2、二人が商談を終えて握手をしています。3、二人が名札を交換しています。4、二人が会議資料を廃棄しています。","visual":{"kind":"emoji","scene":"🤝","sub":"👨‍💼　📁　👩‍💼"}},{"id":"M01-P1-S2-Q06","part":1,"section":2,"type":"listening_response","prompt":"","options":["来週の打ち合わせ、木曜日に変えてください。","恐れ入りますが、来週火曜日のお打ち合わせを木曜日に変更させていただくことは可能でしょうか。","木曜日なら会ってあげられます。","火曜日は無理なので、木曜日にします。"],"answer":2,"b":0.0,"explanation":"こちら都合の変更依頼なので、謝意・配慮を示す②が最も適切。","audioText":"顧客との打ち合わせ日程をこちらの都合で変更したい場面です。最も適切な言い方はどれですか。 1、来週の打ち合わせ、木曜日に変えてください。 2、恐れ入りますが、来週火曜日のお打ち合わせを木曜日に変更させていただくことは可能でしょうか。 3、木曜日なら会ってあげられます。 4、火曜日は無理なので、木曜日にします。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q07","part":1,"section":2,"type":"listening_response","prompt":"","options":["入力を間違えられました。","入力ミスがあったそうです。","私の確認不足で入力を誤ってしまいました。申し訳ありません。すぐに修正いたします。","ちょっと間違えただけです。"],"answer":3,"b":-0.1,"explanation":"自分の責任を明確にし、謝罪と対応を伝える③。","audioText":"部下が自分の入力ミスを上司に報告する場面です。最も適切なのはどれですか。 1、入力を間違えられました。 2、入力ミスがあったそうです。 3、私の確認不足で入力を誤ってしまいました。申し訳ありません。すぐに修正いたします。 4、ちょっと間違えただけです。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q08","part":1,"section":2,"type":"listening_response","prompt":"","options":["部長に代わってあげます。","部長を呼んできます。","ただいま部長におつなぎいたします。少々お待ちください。","部長がいらっしゃいますので待ってください。"],"answer":3,"b":-0.2,"explanation":"社外の相手に社内の部長を高めず、「おつなぎいたします」が自然。","audioText":"取引先から部長宛ての電話です。部長は在席しています。電話を取り次ぐとき何と言いますか。 1、部長に代わってあげます。 2、部長を呼んできます。 3、ただいま部長におつなぎいたします。少々お待ちください。 4、部長がいらっしゃいますので待ってください。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q09","part":1,"section":2,"type":"listening_response","prompt":"","options":["昨日発送したはずです。もう一度確認してください。","申し訳ございません。至急状況を確認し、こちらから折り返しご連絡いたします。","運送会社の問題ですので、そちらへ連絡してください。","今忙しいので後でお願いします。"],"answer":2,"b":-0.1,"explanation":"まず謝罪し、自社側で確認して折り返す②が適切。","audioText":"納品が遅れていると顧客から苦情を受けました。最初の対応として最も適切なのはどれですか。 1、昨日発送したはずです。もう一度確認してください。 2、申し訳ございません。至急状況を確認し、こちらから折り返しご連絡いたします。 3、運送会社の問題ですので、そちらへ連絡してください。 4、今忙しいので後でお願いします。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q10","part":1,"section":2,"type":"listening_response","prompt":"","options":["父は何かおっしゃっていましたか。","父は何か言っておりましたか。","父は何か申しておられましたか。","父は何か言っていらっしゃいましたか。"],"answer":2,"b":1.0,"explanation":"自分側の父を高めないため「言っておりました」が適切。","audioText":"上司があなたに『お父様から電話があったよ』と言いました。自分の父について上司に尋ねる場合、最も適切なのはどれですか。 1、父は何かおっしゃっていましたか。 2、父は何か言っておりましたか。 3、父は何か申しておられましたか。 4、父は何か言っていらっしゃいましたか。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q11","part":1,"section":2,"type":"listening_response","prompt":"","options":["今日は帰ります。","帰ってもいいですか。","恐れ入りますが、体調が優れないため、本日は早退させていただいてもよろしいでしょうか。","早退して差し上げます。"],"answer":3,"b":0.0,"explanation":"許可を求める「～させていただいてもよろしいでしょうか」が適切。","audioText":"体調が悪く、上司に早退の許可を求める場面です。最も適切なのはどれですか。 1、今日は帰ります。 2、帰ってもいいですか。 3、恐れ入りますが、体調が優れないため、本日は早退させていただいてもよろしいでしょうか。 4、早退して差し上げます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q12","part":1,"section":2,"type":"listening_response","prompt":"","options":["ご予約はしていますか。","お約束のお時間とお名前を頂戴してもよろしいでしょうか。","誰に会いたいですか。","予約した人はどなたですか。"],"answer":2,"b":0.1,"explanation":"受付の丁寧な確認として②が自然。","audioText":"会社の受付で、予約のある来客に応対しています。最も自然なのはどれですか。 1、ご予約はしていますか。 2、お約束のお時間とお名前を頂戴してもよろしいでしょうか。 3、誰に会いたいですか。 4、予約した人はどなたですか。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q13","part":1,"section":2,"type":"listening_response","prompt":"","options":["それは無理です。","できませんのでご了承ください。","大変恐縮ですが、品質を確保するため、現状の日程より前倒しすることは難しい状況です。","こちらも困ります。"],"answer":3,"b":0.9,"explanation":"理由を添えて婉曲に断る③が商務上自然。","audioText":"取引先から無理な納期短縮を依頼されました。断り方として最も適切なのはどれですか。 1、それは無理です。 2、できませんのでご了承ください。 3、大変恐縮ですが、品質を確保するため、現状の日程より前倒しすることは難しい状況です。 4、こちらも困ります。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q14","part":1,"section":2,"type":"listening_response","prompt":"","options":["ご指摘ありがとうございます。修正のうえ、改めて提出いたします。","直しておきましたから見てください。","言われた通りにしました。","間違いはもうないと思います。"],"answer":1,"b":-0.1,"explanation":"指摘への謝意と再提出を明確にする①。","audioText":"上司から資料の誤りを指摘され、修正版を出す場面です。最も適切なのはどれですか。 1、ご指摘ありがとうございます。修正のうえ、改めて提出いたします。 2、直しておきましたから見てください。 3、言われた通りにしました。 4、間違いはもうないと思います。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S2-Q15","part":1,"section":2,"type":"listening_response","prompt":"","options":["佐藤さんはいらっしゃいません。","佐藤はただいま外出しております。戻り次第、こちらからお電話するよう申し伝えましょうか。","佐藤は出かけています。後でかけてください。","佐藤様は外出なさっています。"],"answer":2,"b":0.4,"explanation":"社外には社内者を高めず「佐藤は外出しております」。伝言提案も丁寧。","audioText":"取引先から同僚の佐藤さん宛てに電話がありましたが、佐藤さんは外出中です。最も適切なのはどれですか。 1、佐藤さんはいらっしゃいません。 2、佐藤はただいま外出しております。戻り次第、こちらからお電話するよう申し伝えましょうか。 3、佐藤は出かけています。後でかけてください。 4、佐藤様は外出なさっています。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M01-P1-S3-Q16","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["テレビ広告を出す","展示会に出展する","取引先を訪問する","価格を下げる"],"answer":3,"b":0.0,"explanation":"最後に「営業担当が訪問して反応を見る」と決定している。","audioText":"部長：新商品の知名度を上げたいんだが、広告は予算が厳しいな。社員：展示会も費用がかかりますね。ただ、既存の取引先を一社ずつ回って実物を見せれば、費用は抑えられます。部長：そうだな。まず営業担当が訪問して反応を見よう。 二人は最初にどの方法を取ることにしましたか。 1、テレビ広告を出す。 2、展示会に出展する。 3、取引先を訪問する。 4、価格を下げる。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"新商品の売り込み方法"}},{"id":"M01-P1-S3-Q17","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["第1会議室","第2会議室","第3会議室","役員室"],"answer":2,"b":-0.4,"explanation":"第1は使用不可、第3は定員不足なので第2。","audioText":"女：午後の会議、第3会議室でしたよね。男：そうなんだけど、参加者が12人に増えたんだ。第3は8人までだから、第1か第2に変えないと。女：第1は午後ずっと役員会で使います。男：じゃあ第2を押さえてください。 会議はどこで行いますか。 1、第1会議室。 2、第2会議室。 3、第3会議室。 4、役員室。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"会議室変更"}},{"id":"M01-P1-S3-Q18","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["24日に半数だけ","25日午前中に全量","27日に残り","月末に全量"],"answer":2,"b":0.3,"explanation":"最後に別倉庫から手配し25日午前全量で合意。","audioText":"客：できれば今月25日までに納品してほしいのですが。担当：通常は月末ですが、在庫を確認したところ24日に半数、27日に残りを出荷できます。客：25日までに全部必要なんです。担当：それでしたら別倉庫から手配して、25日午前中に全量納品します。 最終的な納品予定はいつですか。 1、24日に半数だけ。 2、25日午前中に全量。 3、27日に残り。 4、月末に全量。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"納期調整"}},{"id":"M01-P1-S3-Q19","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["発注を見送る","20個発注する","50個発注する","60個廃棄する"],"answer":3,"b":-0.1,"explanation":"キャンペーン需要を見込み50個追加発注。","audioText":"女：A商品の在庫が30個まで減りました。男：安全在庫は20個だから、まだ大丈夫じゃない？女：来週のキャンペーンで60個ほど出る見込みです。男：それなら今週中に50個追加発注しておこう。 男の人は何をすることにしましたか。 1、発注を見送る。 2、20個発注する。 3、50個発注する。 4、60個廃棄する。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"在庫補充"}},{"id":"M01-P1-S3-Q20","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["19日","20日","21日","22日"],"answer":3,"b":-0.2,"explanation":"途中で20日と言うが、最終決定は21日。","audioText":"部長：19日の帰りの便だけど、取引先との面談が入ったから一日延ばしてくれないか。秘書：20日ですね。部長：念のため、面談後にもう一泊して21日にしよう。秘書：承知しました。 秘書は何日の便を予約しますか。 1、19日。 2、20日。 3、21日。 4、22日。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"出張便変更"}},{"id":"M01-P1-S3-Q21","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["A社","B社","同額","判断できない"],"answer":1,"b":0.8,"explanation":"3年間総額でA社450万、B社510万。","audioText":"男：新システムはA社が450万円、B社が390万円です。女：A社は保守費込みですが、B社は年間40万円の保守費が別ですね。男：3年間使うなら、A社450万円、B社は510万円か。女：それならA社の方が総額は低いですね。 二人はどちらが経済的だと考えていますか。 1、A社。 2、B社。 3、同額。 4、判断できない。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"予算選択"}},{"id":"M01-P1-S3-Q22","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["火曜午前","火曜午後","木曜9時","木曜10時"],"answer":3,"b":-0.5,"explanation":"木曜9時に決定。","audioText":"人事：候補者は火曜の午後か木曜の午前なら都合がいいそうです。部長：火曜は出張で不在だ。木曜は10時から会議だけど、9時なら大丈夫。人事：では木曜9時で連絡します。 面接はいつになりましたか。 1、火曜午前。 2、火曜午後。 3、木曜9時。 4、木曜10時。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"面接日程"}},{"id":"M01-P1-S3-Q23","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["100台・5％引き","100台・10％引き","120台・5％引き","120台・10％引き"],"answer":4,"b":0.0,"explanation":"数量を120台へ増やし10%引き。","audioText":"客：100台注文するので、10％値引きできますか。営業：通常は5％ですが、120台以上なら10％まで可能です。客：では120台に増やします。営業：ありがとうございます。10％引きでお見積もりします。 最終的な注文条件はどれですか。 1、100台・5％引き。 2、100台・10％引き。 3、120台・5％引き。 4、120台・10％引き。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"値引条件"}},{"id":"M01-P1-S3-Q24","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["4人","7人","9人","12人"],"answer":1,"b":0.2,"explanation":"48+3+5=56、定員60なので4人。","audioText":"女：セミナー申込は今朝の時点で48人です。男：講師側が3人、運営が5人参加します。女：会場の定員は60人なので、一般申込はあと何人受けられますか。男：参加総数を60以内にするなら、あと4人ですね。 一般申込はあと何人受けられますか。 1、4人。 2、7人。 3、9人。 4、12人。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"セミナー人数"}},{"id":"M01-P1-S3-Q25","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["配送会社を変更する","原因調査を完了する","顧客へ現状を連絡する","担当者を処分する"],"answer":3,"b":0.4,"explanation":"調査と並行して、まず顧客への連絡を優先。","audioText":"課長：今回のクレーム、原因は配送ミスだが、まずお客様への連絡が先だ。社員：原因調査を終えてからではなく？課長：調査は並行して進める。ただ、お待たせしているので、現状と今後の連絡予定を今日中に伝えて。 課長が最優先だと言っているのは何ですか。 1、配送会社を変更する。 2、原因調査を完了する。 3、顧客へ現状を連絡する。 4、担当者を処分する。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"苦情対応"}},{"id":"M01-P2-S1-Q26","part":2,"section":1,"type":"listen_read_scene","prompt":"二人は何について話していますか。","options":["価格交渉","数量の相違","電話マナー","採用面接"],"answer":2,"b":-0.8,"explanation":"取引先から数量が注文書と違うという連絡。","audioText":"営業：昨日納品した製品について、取引先から『数量が注文書と違う』と連絡がありました。倉庫：出荷記録を確認します。 二人は何について話していますか。","visual":{"kind":"note","title":"社内チャット","lines":["営業：取引先から連絡あり","倉庫：出荷記録を確認"]}},{"id":"M01-P2-S1-Q27","part":2,"section":1,"type":"listen_read_scene","prompt":"返信内容として最も適切なのはどれですか。","options":["水曜のままでお願いします。","木曜は終日可能です。","木曜の15時以降でしたら対応可能です。","来週は訪問できません。"],"answer":3,"b":-0.4,"explanation":"木曜15時以降が可能。","audioText":"担当：先方から『来週水曜の訪問を木曜に変更できないか』というメールです。課長：木曜なら午後3時以降なら空いていると返信してください。 返信内容として最も適切なのはどれですか。","visual":{"kind":"note","title":"受信メール","lines":["訪問日：水曜 → 木曜希望","時間：未指定"]}},{"id":"M01-P2-S1-Q28","part":2,"section":1,"type":"listen_read_scene","prompt":"午後7時に利用できるのはどれですか。","options":["東側エレベーター","西側エレベーター","どちらも利用不可","階段のみ"],"answer":2,"b":-0.9,"explanation":"18時以降は東側停止、西側利用。","audioText":"アナウンス：本日は設備点検のため、午後6時以降、東側エレベーターはご利用いただけません。西側をご利用ください。 午後7時に利用できるのはどれですか。","visual":{"kind":"notice","title":"設備点検のお知らせ","lines":["東側EV：18:00以降停止","西側EV：通常運転"]}},{"id":"M01-P2-S1-Q29","part":2,"section":1,"type":"listen_read_scene","prompt":"担当者が支払申請に記載する内容はどれですか。","options":["手数料は先方負担","支払期限は翌月末","手数料は自社負担","現金で支払う"],"answer":3,"b":-0.5,"explanation":"振込手数料は当社負担。","audioText":"経理：この請求書、支払期限は月末ですが、振込手数料は当社負担と書いてあります。担当：では支払申請にその条件も記載します。 担当者が支払申請に記載する内容はどれですか。","visual":{"kind":"invoice","title":"請求書","lines":["支払期限：9月30日","振込手数料：買主負担"]}},{"id":"M01-P2-S1-Q30","part":2,"section":1,"type":"listen_read_scene","prompt":"女性はメモに何と書きますか。","options":["明日の訪問を中止","明日の訪問を10時開始","明日の訪問を11時開始に変更希望","今日11時に訪問"],"answer":3,"b":-0.6,"explanation":"10時から11時へ変更希望。","audioText":"女性：山田部長はただいま会議中です。男性：では、明日の訪問時間を10時から11時に変更したいとお伝えください。女性：承知しました。 女性はメモに何と書きますか。","visual":{"kind":"note","title":"電話メモ","lines":["宛先：山田部長","用件：明日の訪問時間"]}},{"id":"M01-P2-S2-Q31","part":2,"section":2,"type":"listen_read_data","prompt":"次の表は4支店の前年と今年の売上です。増加額が最も大きい支店はどこですか。","options":["東京","大阪","名古屋","福岡"],"answer":2,"b":-0.3,"explanation":"増加額は東京10、大阪20、名古屋8、福岡15なので大阪。","audioText":"次の表は4支店の前年と今年の売上です。増加額が最も大きい支店はどこですか。","visual":{"kind":"table","title":"売上（百万円）","headers":["支店","前年","今年"],"rows":[["東京","120","130"],["大阪","95","115"],["名古屋","80","88"],["福岡","70","85"]]}},{"id":"M01-P2-S2-Q32","part":2,"section":2,"type":"listen_read_data","prompt":"次の予約表を見てください。14時から16時まで10人で会議をしたい場合、利用できる会議室はどれですか。","options":["A","B","C","D"],"answer":3,"b":0.0,"explanation":"Cは12名定員で14-16時空き。Aは定員不足、B予約あり、Dは15時から予約。","audioText":"次の予約表を見てください。14時から16時まで10人で会議をしたい場合、利用できる会議室はどれですか。","visual":{"kind":"table","title":"会議室予約","headers":["室","定員","14-15","15-16"],"rows":[["A","8","空","空"],["B","12","予約","空"],["C","12","空","空"],["D","20","空","予約"]]}},{"id":"M01-P2-S2-Q33","part":2,"section":2,"type":"listen_read_data","prompt":"荷物は3.2kgです。翌日午前指定で送るとき、最も安い会社はどこですか。","options":["A便","B便","C便","D便"],"answer":2,"b":0.4,"explanation":"3.2kgの基本料金＋翌朝加算はA 980+300=1280、B 1050+150=1200、C 900+400=1300、D 1150+100=1250。Bが最安。","audioText":"荷物は3.2kgです。翌日午前指定で送るとき、最も安い会社はどこですか。","visual":{"kind":"table","title":"宅配料金","headers":["会社","3-5kg","翌朝加算"],"rows":[["A便","980","300"],["B便","1050","150"],["C便","900","400"],["D便","1150","100"]]}},{"id":"M01-P2-S2-Q34","part":2,"section":2,"type":"listen_read_data","prompt":"出張で2泊します。朝食が必要で、1泊あたり1万円以内にしたい場合、どのプランが条件に合いますか。","options":["A","B","C","D"],"answer":4,"b":-0.2,"explanation":"Dは9,800円で朝食あり。Bは朝食なし、A/Cは1万円超。","audioText":"出張で2泊します。朝食が必要で、1泊あたり1万円以内にしたい場合、どのプランが条件に合いますか。","visual":{"kind":"table","title":"宿泊プラン","headers":["プラン","1泊","朝食"],"rows":[["A","10,800円","あり"],["B","8,900円","なし"],["C","10,200円","あり"],["D","9,800円","あり"]]}},{"id":"M01-P2-S2-Q35","part":2,"section":2,"type":"listen_read_data","prompt":"会社は10,000米ドルを購入します。手数料込みで支払額が最も少ない銀行はどこですか。","options":["A銀行","B銀行","C銀行","D銀行"],"answer":1,"b":1.1,"explanation":"A:151.2*10000+2000=1,514,000。B=1,515,000、C=1,514,500、D=1,515,500。A最安。","audioText":"会社は10,000米ドルを購入します。手数料込みで支払額が最も少ない銀行はどこですか。","visual":{"kind":"table","title":"USD販売レート","headers":["銀行","円/USD","手数料"],"rows":[["A銀行","151.2","2,000円"],["B銀行","151.0","5,000円"],["C銀行","151.4","500円"],["D銀行","150.8","7,500円"]]}},{"id":"M01-P2-S2-Q36","part":2,"section":2,"type":"listen_read_data","prompt":"月12,000枚印刷します。月額総費用が最も低い会社はどこですか。","options":["A社","B社","C社","D社"],"answer":3,"b":1.1,"explanation":"A 25,000+12,000*1.2=39,400。B=39,600。C=28,000+9,600=37,600。D=38,200。C最安。","audioText":"月12,000枚印刷します。月額総費用が最も低い会社はどこですか。","visual":{"kind":"table","title":"コピー機リース","headers":["会社","基本料/月","1枚"],"rows":[["A社","25,000","1.2円"],["B社","30,000","0.8円"],["C社","28,000","0.8円"],["D社","22,000","1.35円"]]}},{"id":"M01-P2-S2-Q37","part":2,"section":2,"type":"listen_read_data","prompt":"13時に急な来客があります。13時に社内にいる営業担当は誰ですか。","options":["佐藤","鈴木","田中","高橋"],"answer":4,"b":-0.2,"explanation":"高橋のみ12-14時が社内。","audioText":"13時に急な来客があります。13時に社内にいる営業担当は誰ですか。","visual":{"kind":"table","title":"営業部予定","headers":["氏名","12-14時"],"rows":[["佐藤","客先訪問"],["鈴木","昼食・移動"],["田中","展示会"],["高橋","社内"]]}},{"id":"M01-P2-S2-Q38","part":2,"section":2,"type":"listen_read_data","prompt":"安全在庫を下回っていて、かつ来週の入荷予定がない商品はどれですか。","options":["A","B","C","D"],"answer":2,"b":0.2,"explanation":"Bは現在10、安全15、入荷0。Dは下回るが入荷あり。","audioText":"安全在庫を下回っていて、かつ来週の入荷予定がない商品はどれですか。","visual":{"kind":"table","title":"在庫状況","headers":["商品","現在庫","安全在庫","来週入荷"],"rows":[["A","30","20","0"],["B","10","15","0"],["C","18","15","20"],["D","8","12","30"]]}},{"id":"M01-P2-S2-Q39","part":2,"section":2,"type":"listen_read_data","prompt":"新入社員は平日の午後のみ参加できます。費用が2万円以下で、2日間以上の研修はどれですか。","options":["A","B","C","D"],"answer":3,"b":0.3,"explanation":"Cは平日午後、2日、18,000円。","audioText":"新入社員は平日の午後のみ参加できます。費用が2万円以下で、2日間以上の研修はどれですか。","visual":{"kind":"table","title":"研修プラン","headers":["研修","時間","日数","費用"],"rows":[["A","平日午前","3","15,000"],["B","土日午後","2","18,000"],["C","平日午後","2","18,000"],["D","平日午後","1","12,000"]]}},{"id":"M01-P2-S2-Q40","part":2,"section":2,"type":"listen_read_data","prompt":"固定費が月120万円、1個あたり販売価格5,000円、変動費3,000円です。損益分岐点の販売数量はどれですか。","options":["400個","500個","600個","800個"],"answer":3,"b":1.0,"explanation":"限界利益2,000円、1,200,000÷2,000=600個。","audioText":"固定費が月120万円、1個あたり販売価格5,000円、変動費3,000円です。損益分岐点の販売数量はどれですか。","visual":{"kind":"table","title":"月次条件","headers":["固定費","販売価格","変動費"],"rows":[["1,200,000円","5,000円/個","3,000円/個"]]}},{"id":"M01-P2-S3-Q41","part":2,"section":3,"type":"listen_read_dialogue","prompt":"来賓挨拶はどこに入りますか。","options":["開会直後","基調講演の前","休憩の後","閉会の後"],"answer":3,"b":0.2,"explanation":"到着遅延により休憩を先にし、その後来賓挨拶。","audioText":"司会：来賓の挨拶は当初13時40分でしたが、到着が15分遅れるそうです。休憩を先に10分入れ、その後に来賓挨拶を行いましょう。 来賓挨拶はどこに入りますか。","visual":{"kind":"agenda","title":"セミナー式次第","lines":["13:00 開会","13:10 基調講演","13:40 来賓挨拶（変更前）","14:00 パネル討論"]}},{"id":"M01-P2-S3-Q42","part":2,"section":3,"type":"listen_read_dialogue","prompt":"該当する会社はどれですか。","options":["A社","B社","C社","D社"],"answer":2,"b":0.9,"explanation":"B社だけ売上増・利益減。","audioText":"説明者：4社のうち、売上が増えたにもかかわらず営業利益が減った会社は、原材料高の影響を最も受けた会社です。 該当する会社はどれですか。","visual":{"kind":"table","title":"決算（前年比）","headers":["会社","売上","営業利益"],"rows":[["A社","+5%","+3%"],["B社","+8%","-4%"],["C社","-2%","-1%"],["D社","+1%","+1%"]]}},{"id":"M01-P2-S3-Q43","part":2,"section":3,"type":"listen_read_dialogue","prompt":"変更後の列車はどれですか。","options":["17:00発","17:30発","18:00発","20:30発"],"answer":3,"b":-0.4,"explanation":"18時発へ変更。20:30は到着時刻。","audioText":"上司：大阪での面談が16時まで延びた。17時の新幹線は間に合わないな。秘書：18時発なら空席があります。東京着は20時30分です。上司：それでお願いします。 変更後の列車はどれですか。","visual":{"kind":"table","title":"帰路候補","headers":["便","大阪発","東京着"],"rows":[["A","17:00","19:30"],["B","17:30","20:00"],["C","18:00","20:30"],["D","20:30","23:00"]]}},{"id":"M01-P2-S3-Q44","part":2,"section":3,"type":"listen_read_dialogue","prompt":"急な事情で明日在宅勤務したい場合、必要なのはどれですか。","options":["申請不要","所属長の承認","人事部長の承認","1週間前の申請"],"answer":2,"b":0.0,"explanation":"例外として所属長承認があれば前日可。","audioText":"人事：申請は原則3営業日前までですが、急な事情がある場合は所属長の承認があれば前日でも可能です。 急な事情で明日在宅勤務したい場合、必要なのはどれですか。","visual":{"kind":"notice","title":"在宅勤務規程","lines":["原則：3営業日前まで","例外：急な事情＋所属長承認"]}},{"id":"M01-P2-S3-Q45","part":2,"section":3,"type":"listen_read_dialogue","prompt":"来月の計画として正しいのはどれですか。","options":["A 1,000 / B 800","A 1,200 / B 600","A 1,200 / B 800","A 1,000 / B 600"],"answer":2,"b":-0.3,"explanation":"発言通りA1200、B600。","audioText":"工場長：A製品は需要予測が20％上がったので1,200台に増産します。B製品は部品不足で800台から600台に減らします。 来月の計画として正しいのはどれですか。","visual":{"kind":"table","title":"今月計画","headers":["製品","台数"],"rows":[["A","1,000"],["B","800"]]}},{"id":"M01-P2-S3-Q46","part":2,"section":3,"type":"listen_read_dialogue","prompt":"次回、予算を増やす広告はどれですか。","options":["A","B","両方同額","広告を中止"],"answer":2,"b":0.1,"explanation":"獲得費用が低く購入率の高いB。","audioText":"担当：広告Aはクリック率が高いですが購入率が低いです。広告Bはクリック率は低いものの購入率が高く、1件あたり獲得費用も最も低いです。次回はBに予算を寄せます。 次回、予算を増やす広告はどれですか。","visual":{"kind":"table","title":"広告実績","headers":["広告","CTR","購入率","獲得費"],"rows":[["A","8%","1%","5,000"],["B","4%","4%","2,200"]]}},{"id":"M01-P2-S3-Q47","part":2,"section":3,"type":"listen_read_dialogue","prompt":"C社には何時ごろ着く予定ですか。","options":["12:00","12:40","13:00","13:40"],"answer":3,"b":0.2,"explanation":"B社面談後30分昼食＋40分移動で13時面談に合わせる。","audioText":"営業：午前はA社が10時、B社が11時30分です。B社からC社までは移動に40分、C社は13時なら面談できます。昼食はB社の近くで30分取ります。 C社には何時ごろ着く予定ですか。","visual":{"kind":"route","title":"訪問予定","lines":["A社 10:00","B社 11:30","昼食 30分","B→C 40分","C社 13:00面談可"]}},{"id":"M01-P2-S3-Q48","part":2,"section":3,"type":"listen_read_dialogue","prompt":"店長はどうするつもりですか。","options":["土曜夕方を3人で運営","佐々木を夕方へ変更","店を早く閉める","新規採用する"],"answer":2,"b":-0.5,"explanation":"不足1名を佐々木のシフト変更で補う。","audioText":"店長：土曜の夕方は来客が多いので4人必要です。現状は3人しか入っていません。佐々木さんは午前だけの予定ですが、夕方へ変更可能とのことです。 店長はどうするつもりですか。","visual":{"kind":"table","title":"土曜シフト","headers":["時間","必要","現在"],"rows":[["午前","3","4"],["夕方","4","3"]]}},{"id":"M01-P2-S3-Q49","part":2,"section":3,"type":"listen_read_dialogue","prompt":"B社を選ぶ主な理由はどれですか。","options":["単価が最安","納期条件を満たす","保証がない","4週間で届く"],"answer":2,"b":-0.1,"explanation":"3週間以内という必須条件を満たすB社。","audioText":"担当：A社は単価が最安ですが納期が4週間です。B社は少し高いものの2週間で、品質保証も3年あります。今回は3週間以内に必要なのでB社を提案します。 B社を選ぶ主な理由はどれですか。","visual":{"kind":"table","title":"見積比較","headers":["会社","単価","納期","保証"],"rows":[["A","9,000","4週","1年"],["B","9,600","2週","3年"]]}},{"id":"M01-P2-S3-Q50","part":2,"section":3,"type":"listen_read_dialogue","prompt":"最優先するリスクはどれですか。","options":["備品不足","情報漏えい","会議遅延","軽微な入力ミス"],"answer":2,"b":0.9,"explanation":"影響が非常に大きい情報漏えいを優先。","audioText":"責任者：発生確率が低くても影響が非常に大きい情報漏えいは、優先して対策します。一方、備品不足は頻度が高いですが影響が小さいので次点です。 最優先するリスクはどれですか。","visual":{"kind":"table","title":"リスク","headers":["項目","発生確率","影響"],"rows":[["備品不足","高","小"],["情報漏えい","低","極大"],["会議遅延","中","小"],["入力ミス","中","小"]]}},{"id":"M01-P3-S1-Q51","part":3,"section":1,"type":"reading_vocab","prompt":"来期の売上は伸びる＿＿が高い。","options":["見込み","目当て","見当","目算"],"answer":1,"b":0.4,"explanation":"将来の可能性・予測は「見込み」。"},{"id":"M01-P3-S1-Q52","part":3,"section":1,"type":"reading_vocab","prompt":"参加人数＿＿会場の大きさを変更します。","options":["に応じて","において","に限って","にかけて"],"answer":1,"b":0.2,"explanation":"条件に合わせて変化するので「に応じて」。"},{"id":"M01-P3-S1-Q53","part":3,"section":1,"type":"reading_vocab","prompt":"取引先から正式な要請があった以上、計画を見直さ＿＿。","options":["ないことはない","ざるを得ない","はずはない","に違いない"],"answer":2,"b":1.1,"explanation":"避けられずそうする必要がある＝「ざるを得ない」。"},{"id":"M01-P3-S1-Q54","part":3,"section":1,"type":"reading_vocab","prompt":"組織改編により、来月から大阪支社へ異動する＿＿。","options":["ことにしました","ことになりました","ようにしました","ことがあります"],"answer":2,"b":0.0,"explanation":"自分の意思より組織決定なので「ことになりました」。"},{"id":"M01-P3-S1-Q55","part":3,"section":1,"type":"reading_vocab","prompt":"本日はお忙しいところ、弊社まで＿＿ありがとうございます。","options":["お越しいただき","いらっしゃっていただき","来てあげて","お越しになっていただき"],"answer":1,"b":1.0,"explanation":"「お越しいただき」が自然な依頼・受益表現。"},{"id":"M01-P3-S1-Q56","part":3,"section":1,"type":"reading_vocab","prompt":"こちらの日程で＿＿なければ、来週火曜日でお願いいたします。","options":["差し支え","差し引き","見込み","都合"],"answer":1,"b":0.1,"explanation":"「差し支えなければ」＝問題がなければ。"},{"id":"M01-P3-S1-Q57","part":3,"section":1,"type":"reading_vocab","prompt":"初めての大型案件なので、担当者は契約締結に＿＿いる。","options":["足を運んで","二の足を踏んで","目を通して","手を貸して"],"answer":2,"b":0.5,"explanation":"躊躇する＝「二の足を踏む」。"},{"id":"M01-P3-S1-Q58","part":3,"section":1,"type":"reading_vocab","prompt":"会議の前に、この資料に一度＿＿おいてください。","options":["耳を傾けて","目を通して","顔を出して","手を打って"],"answer":2,"b":-0.2,"explanation":"資料をざっと読む＝「目を通す」。"},{"id":"M01-P3-S1-Q59","part":3,"section":1,"type":"reading_vocab","prompt":"申請書は＿＿金曜日までに提出してください。","options":["遅くとも","なるべく","さっぱり","あらかじめ"],"answer":1,"b":-0.3,"explanation":"最終期限を示す「遅くとも～までに」。"},{"id":"M01-P3-S1-Q60","part":3,"section":1,"type":"reading_vocab","prompt":"担当変更の＿＿、関係部署へメールでお知らせください。","options":["旨","際","末","上"],"answer":1,"b":0.8,"explanation":"内容・趣旨を表す「～の旨」。"},{"id":"M01-P3-S2-Q61","part":3,"section":2,"type":"reading_expression","prompt":"取引先へのメール冒頭として最も適切なのはどれですか。","options":["いつもどうも。","お世話になっております。株式会社青山の李です。","ご苦労様です。","了解しました。"],"answer":2,"b":-0.6,"explanation":"社外メールの一般的な冒頭は「お世話になっております」。"},{"id":"M01-P3-S2-Q62","part":3,"section":2,"type":"reading_expression","prompt":"顧客から課長への電話を受け、課長が不在のとき最も適切なのはどれですか。","options":["課長様は今いません。","課長はいらっしゃいません。","課長の田中はただいま席を外しております。","田中さんは外出なさっています。"],"answer":3,"b":0.3,"explanation":"社外には社内者を高めず、「席を外しております」。"},{"id":"M01-P3-S2-Q63","part":3,"section":2,"type":"reading_expression","prompt":"取引先からの招待を丁寧に断る表現として最も適切なのはどれですか。","options":["行けません。","せっかくお声がけいただきましたが、あいにく先約があり、今回は辞退させていただきます。","今回はやめます。","都合が悪いので無理です。"],"answer":2,"b":0.0,"explanation":"謝意＋事情＋婉曲な辞退。"},{"id":"M01-P3-S2-Q64","part":3,"section":2,"type":"reading_expression","prompt":"資料の修正を先輩に依頼するとき最も自然なのはどれですか。","options":["ここを直してください。","恐れ入りますが、こちらの数字をご確認のうえ、修正していただけますでしょうか。","ここ、間違っていますよ。","修正なさっていただきたいです。"],"answer":2,"b":0.2,"explanation":"依頼の丁寧さと文型が自然。"},{"id":"M01-P3-S2-Q65","part":3,"section":2,"type":"reading_expression","prompt":"社内で上司から指示を受けたとき、最も適切な返答はどれですか。","options":["了解。","承知しました。","わかったよ。","ご理解しました。"],"answer":2,"b":-0.4,"explanation":"上司への応答は「承知しました」が適切。"},{"id":"M01-P3-S2-Q66","part":3,"section":2,"type":"reading_expression","prompt":"納品遅延について顧客へ謝罪する文として最も適切なのはどれですか。","options":["遅れてすみませんでした。","このたびは納品が遅れ、ご迷惑をおかけしましたことを深くお詫び申し上げます。","配送会社が遅れました。","もう少し待ってください。"],"answer":2,"b":-0.2,"explanation":"正式な謝罪として②。"},{"id":"M01-P3-S2-Q67","part":3,"section":2,"type":"reading_expression","prompt":"会議で上司の案に異論を述べるとき最も適切なのはどれですか。","options":["それは違います。","確かにその点は重要ですが、別の見方もできるのではないでしょうか。","私は反対です。以上です。","その案はだめだと思います。"],"answer":2,"b":0.8,"explanation":"相手を立てつつ別案を示す②。"},{"id":"M01-P3-S2-Q68","part":3,"section":2,"type":"reading_expression","prompt":"不在の担当者から顧客へ折り返し電話することを提案する表現として最も適切なのはどれですか。","options":["戻ったら電話させます。","戻り次第、こちらからお電話するよう申し伝えましょうか。","後で電話しますよ。","またかけてください。"],"answer":2,"b":0.4,"explanation":"伝言＋折返し提案として自然。"},{"id":"M01-P3-S2-Q69","part":3,"section":2,"type":"reading_expression","prompt":"社内通知として最も適切なのはどれですか。","options":["明日は工事なので入れません。","設備工事のため、明日9時から12時まで3階会議室はご利用いただけません。","明日、会議室だめです。","3階を使わないで。"],"answer":2,"b":-0.7,"explanation":"対象・理由・時間・制限が明確。"},{"id":"M01-P3-S2-Q70","part":3,"section":2,"type":"reading_expression","prompt":"まだ確定していない情報を報告するとき最も適切なのはどれですか。","options":["来月必ず値上げします。","現時点では、来月から値上げとなる可能性があります。","値上げに違いありません。","絶対に値上げです。"],"answer":2,"b":0.1,"explanation":"未確定情報なので確度を落とした表現が適切。"},{"id":"M01-P3-S3-Q71","part":3,"section":3,"type":"reading_comprehension","prompt":"制度変更後、原則としていつまでに申請する必要がありますか。","options":["当日","前日","3営業日前","1週間前"],"answer":3,"b":-0.4,"explanation":"原則3営業日前。","passage":"【在宅勤務制度の見直し】\n10月から在宅勤務の申請方法を変更する。従来は前日までの申請でよかったが、原則として3営業日前までに申請することとする。ただし、家族の急病など予測できない事情がある場合は、所属長の承認を得たうえで前日申請も認める。なお、在宅勤務日は週2日までとし、顧客訪問や社内会議がある日は出社を優先する。","passageGroup":"A"},{"id":"M01-P3-S3-Q72","part":3,"section":3,"type":"reading_comprehension","prompt":"例外的に前日申請が認められる条件はどれですか。","options":["週2日以内なら無条件","所属長の承認があり、予測できない事情がある","顧客訪問がある","社内会議がある"],"answer":2,"b":0.1,"explanation":"予測不能な事情＋所属長承認。","passage":"【在宅勤務制度の見直し】\n10月から在宅勤務の申請方法を変更する。従来は前日までの申請でよかったが、原則として3営業日前までに申請することとする。ただし、家族の急病など予測できない事情がある場合は、所属長の承認を得たうえで前日申請も認める。なお、在宅勤務日は週2日までとし、顧客訪問や社内会議がある日は出社を優先する。","passageGroup":"A"},{"id":"M01-P3-S3-Q73","part":3,"section":3,"type":"reading_comprehension","prompt":"最も評価が高かった項目はどれですか。","options":["操作の簡単さ","価格","問い合わせ対応","初回設定説明"],"answer":1,"b":-0.7,"explanation":"78%で操作の簡単さ。","passage":"【顧客アンケート結果】\n新サービス利用者200名にアンケートを行った。『操作が簡単』は78％、『価格に満足』は52％、『問い合わせ対応に満足』は64％だった。一方、自由記述では、初回設定の説明が分かりにくいという意見が多かった。担当チームは価格改定より先に、初回設定ガイドとFAQを改善する方針を決めた。","passageGroup":"B"},{"id":"M01-P3-S3-Q74","part":3,"section":3,"type":"reading_comprehension","prompt":"担当チームが先に改善するのは何ですか。","options":["価格","FAQと初回設定ガイド","問い合わせ窓口の人数","サービス名称"],"answer":2,"b":-0.3,"explanation":"本文の最終方針。","passage":"【顧客アンケート結果】\n新サービス利用者200名にアンケートを行った。『操作が簡単』は78％、『価格に満足』は52％、『問い合わせ対応に満足』は64％だった。一方、自由記述では、初回設定の説明が分かりにくいという意見が多かった。担当チームは価格改定より先に、初回設定ガイドとFAQを改善する方針を決めた。","passageGroup":"B"},{"id":"M01-P3-S3-Q75","part":3,"section":3,"type":"reading_comprehension","prompt":"現時点で確認されている事実はどれですか。","options":["製品事故が発生した","すべての部品が不良だった","一部部品に寸法のばらつきがある","原因が確定した"],"answer":3,"b":0.0,"explanation":"確認済みは一部部品の寸法ばらつき。","passage":"【仕入先への連絡】\n昨日納品された部品の一部に寸法のばらつきが見つかりました。現時点では製品への影響は確認されていませんが、念のため該当ロットの使用を停止しています。つきましては、製造記録をご確認いただき、原因と再発防止策について9月30日までにご回答ください。なお、代替品が必要となる場合は別途数量をご連絡します。","passageGroup":"C"},{"id":"M01-P3-S3-Q76","part":3,"section":3,"type":"reading_comprehension","prompt":"仕入先に求めていることは何ですか。","options":["直ちに全量を交換する","9月30日までに原因と再発防止策を回答する","製品を回収する","代替品を100個送る"],"answer":2,"b":-0.2,"explanation":"明示された依頼事項。","passage":"【仕入先への連絡】\n昨日納品された部品の一部に寸法のばらつきが見つかりました。現時点では製品への影響は確認されていませんが、念のため該当ロットの使用を停止しています。つきましては、製造記録をご確認いただき、原因と再発防止策について9月30日までにご回答ください。なお、代替品が必要となる場合は別途数量をご連絡します。","passageGroup":"C"},{"id":"M01-P3-S3-Q77","part":3,"section":3,"type":"reading_comprehension","prompt":"最終的な移行日はいつですか。","options":["11月1日","11月4日","11月8日","未定"],"answer":2,"b":-0.5,"explanation":"協議結果は11月4日。","passage":"【プロジェクト進捗メモ】\nシステム移行は当初11月1日を予定していたが、データ検証に想定以上の時間を要している。開発チームは11月8日への延期を提案した。一方、営業部は顧客向け告知済みのため、延期幅を最小限にしたいとしている。協議の結果、11月4日に移行し、1日から3日までは旧システムを継続利用することになった。","passageGroup":"D"},{"id":"M01-P3-S3-Q78","part":3,"section":3,"type":"reading_comprehension","prompt":"11月1日から3日はどうしますか。","options":["サービスを停止する","新旧両方を停止する","旧システムを継続利用する","新システムだけを使う"],"answer":3,"b":-0.5,"explanation":"旧システム継続。","passage":"【プロジェクト進捗メモ】\nシステム移行は当初11月1日を予定していたが、データ検証に想定以上の時間を要している。開発チームは11月8日への延期を提案した。一方、営業部は顧客向け告知済みのため、延期幅を最小限にしたいとしている。協議の結果、11月4日に移行し、1日から3日までは旧システムを継続利用することになった。","passageGroup":"D"},{"id":"M01-P3-S3-Q79","part":3,"section":3,"type":"reading_comprehension","prompt":"電子領収書の場合、必要な対応はどれですか。","options":["PDFを添付する","紙の原本も必ず提出する","領収書は不要","出張前に提出する"],"answer":1,"b":-0.8,"explanation":"PDF添付で紙提出不要。","passage":"【出張旅費精算ルール】\n交通費と宿泊費は、出張終了後5営業日以内に精算システムへ入力する。領収書が電子発行された場合はPDFを添付し、紙の領収書を別途提出する必要はない。タクシー利用は原則として事前承認が必要だが、深夜の公共交通機関終了後など緊急の場合は、理由を記載すれば事後申請を認める。私用の飲食費は精算対象外である。","passageGroup":"E"},{"id":"M01-P3-S3-Q80","part":3,"section":3,"type":"reading_comprehension","prompt":"タクシーを事後申請できるのはどのような場合ですか。","options":["いつでも可能","私用の場合","緊急事情があり理由を記載する場合","料金が安い場合"],"answer":3,"b":-0.2,"explanation":"緊急例外＋理由記載。","passage":"【出張旅費精算ルール】\n交通費と宿泊費は、出張終了後5営業日以内に精算システムへ入力する。領収書が電子発行された場合はPDFを添付し、紙の領収書を別途提出する必要はない。タクシー利用は原則として事前承認が必要だが、深夜の公共交通機関終了後など緊急の場合は、理由を記載すれば事後申請を認める。私用の飲食費は精算対象外である。","passageGroup":"E"}]},"BJT-MOCK-02":{"id":"BJT-MOCK-02","code":"MOCK 02","title":"模擬試驗 第2回","questions":[{"id":"M02-P1-S1-Q01","part":1,"section":1,"type":"listening_scene","prompt":"","options":["男性が受付で入館証を受け取っています。","男性が郵便物を仕分けています。","男性が会議室を掃除しています。","男性が商品を包装しています。"],"answer":1,"b":-1.0,"explanation":"受付でカードを受け取る場面なので①。","audioText":"1、男性が受付で入館証を受け取っています。 2、男性が郵便物を仕分けています。 3、男性が会議室を掃除しています。 4、男性が商品を包装しています。","visual":{"kind":"emoji","scene":"🧑‍💼 ← 🪪 👩‍💼","sub":"受付"}},{"id":"M02-P1-S1-Q02","part":1,"section":1,"type":"listening_scene","prompt":"","options":["女性がホワイトボードに予定を書いています。","女性がコピー用紙を補充しています。","女性が顧客に名刺を渡しています。","女性が棚から商品を取っています。"],"answer":3,"b":-0.8,"explanation":"来客と向き合い名刺を差し出しているため③。","audioText":"1、女性がホワイトボードに予定を書いています。 2、女性がコピー用紙を補充しています。 3、女性が顧客に名刺を渡しています。 4、女性が棚から商品を取っています。","visual":{"kind":"emoji","scene":"👩‍💼 🪪➡️ 👨‍💼","sub":"応接スペース"}},{"id":"M02-P1-S1-Q03","part":1,"section":1,"type":"listening_scene","prompt":"","options":["二人が倉庫で在庫を確認しています。","二人がレストランで注文しています。","二人が面接結果を電話しています。","二人が駅で切符を買っています。"],"answer":1,"b":-0.7,"explanation":"箱の数量を照合しているので①。","audioText":"1、二人が倉庫で在庫を確認しています。 2、二人がレストランで注文しています。 3、二人が面接結果を電話しています。 4、二人が駅で切符を買っています。","visual":{"kind":"emoji","scene":"📦📦 👥 📝","sub":"倉庫"}},{"id":"M02-P1-S1-Q04","part":1,"section":1,"type":"listening_scene","prompt":"","options":["社員がプロジェクターを設置しています。","社員が顧客を見送っています。","社員が封筒に切手を貼っています。","社員が商品を返品しています。"],"answer":1,"b":-0.9,"explanation":"会議室で投影機器を準備しているので①。","audioText":"1、社員がプロジェクターを設置しています。 2、社員が顧客を見送っています。 3、社員が封筒に切手を貼っています。 4、社員が商品を返品しています。","visual":{"kind":"emoji","scene":"🧑‍💼 🔌 📽️","sub":"会議室"}},{"id":"M02-P1-S1-Q05","part":1,"section":1,"type":"listening_scene","prompt":"","options":["女性が電話のメモを取っています。","女性が契約書を破棄しています。","女性が荷物を運んでいます。","女性が商品の値札を替えています。"],"answer":1,"b":-0.8,"explanation":"受話器を持ちメモを書いているので①。","audioText":"1、女性が電話のメモを取っています。 2、女性が契約書を破棄しています。 3、女性が荷物を運んでいます。 4、女性が商品の値札を替えています。","visual":{"kind":"emoji","scene":"☎️ 👩‍💼 📝","sub":"オフィス"}},{"id":"M02-P1-S2-Q06","part":1,"section":2,"type":"listening_response","prompt":"","options":["資料はまだです。","申し訳ございません。確認に時間を要しており、本日中にお送りいたします。","あとで送ると思います。","待っていただきます。"],"answer":2,"b":0.1,"explanation":"謝罪、理由、具体的な対応を示す②。","audioText":"顧客に資料の送付が遅れることを伝える場面です。 最も適切なのはどれですか。 1、資料はまだです。 2、申し訳ございません。確認に時間を要しており、本日中にお送りいたします。 3、あとで送ると思います。 4、待っていただきます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q07","part":1,"section":2,"type":"listening_response","prompt":"","options":["承知しました。すぐに対応いたします。","コピーしてあげます。","今はちょっと無理です。","コピーなさいます。"],"answer":1,"b":-0.4,"explanation":"上司の依頼を受ける返答として①。","audioText":"上司から急ぎのコピーを頼まれました。 最も適切なのはどれですか。 1、承知しました。すぐに対応いたします。 2、コピーしてあげます。 3、今はちょっと無理です。 4、コピーなさいます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q08","part":1,"section":2,"type":"listening_response","prompt":"","options":["山田さんを呼んでください。","山田様はいらっしゃいますか。","山田様にお目にかかりたいのですが、お取り次ぎいただけますでしょうか。","山田様を出してください。"],"answer":3,"b":0.7,"explanation":"訪問先での丁寧な取次依頼は③。","audioText":"訪問先で担当者を呼んでもらう場面です。 最も適切なのはどれですか。 1、山田さんを呼んでください。 2、山田様はいらっしゃいますか。 3、山田様にお目にかかりたいのですが、お取り次ぎいただけますでしょうか。 4、山田様を出してください。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q09","part":1,"section":2,"type":"listening_response","prompt":"","options":["部長の佐藤様が申し上げました。","部長の佐藤がおっしゃいました。","部長の佐藤が申しておりました。","部長の佐藤様が言われました。"],"answer":3,"b":0.8,"explanation":"社外には自社側を高めず謙譲語「申す」。","audioText":"自社の部長について取引先に説明します。 最も適切なのはどれですか。 1、部長の佐藤様が申し上げました。 2、部長の佐藤がおっしゃいました。 3、部長の佐藤が申しておりました。 4、部長の佐藤様が言われました。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q10","part":1,"section":2,"type":"listening_response","prompt":"","options":["5分待って。","恐れ入りますが、開始まで今しばらくお待ちいただけますでしょうか。","5分待たせていただきます。","待ってあげてください。"],"answer":2,"b":0.2,"explanation":"依頼として丁寧で自然なのは②。","audioText":"会議開始を5分待ってもらうよう参加者へ伝えます。 最も適切なのはどれですか。 1、5分待って。 2、恐れ入りますが、開始まで今しばらくお待ちいただけますでしょうか。 3、5分待たせていただきます。 4、待ってあげてください。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q11","part":1,"section":2,"type":"listening_response","prompt":"","options":["こちらでは合っています。","ご指摘ありがとうございます。至急確認のうえ、訂正した請求書をお送りいたします。","経理のせいです。","次回直します。"],"answer":2,"b":-0.1,"explanation":"謝意・確認・是正を明確にする②。","audioText":"顧客から誤請求を指摘されました。 最も適切なのはどれですか。 1、こちらでは合っています。 2、ご指摘ありがとうございます。至急確認のうえ、訂正した請求書をお送りいたします。 3、経理のせいです。 4、次回直します。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q12","part":1,"section":2,"type":"listening_response","prompt":"","options":["今日は来てくれてどうも。","本日はお越しいただき、誠にありがとうございました。","今日はおいでになってもらってありがとう。","また来てくださいね。"],"answer":2,"b":0.0,"explanation":"来客への感謝として②。","audioText":"面談後、来客をエレベーターまで見送ります。 最も適切なのはどれですか。 1、今日は来てくれてどうも。 2、本日はお越しいただき、誠にありがとうございました。 3、今日はおいでになってもらってありがとう。 4、また来てくださいね。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q13","part":1,"section":2,"type":"listening_response","prompt":"","options":["この資料、出して。","悪いけど、これ出してくれる？","恐れ入りますが、こちらの資料を総務へ提出していただけますか。","提出して差し上げますか。"],"answer":3,"b":0.1,"explanation":"職場で丁寧に依頼する③。","audioText":"同僚に自分の代わりに資料を提出してもらいたい場面です。 最も適切なのはどれですか。 1、この資料、出して。 2、悪いけど、これ出してくれる？ 3、恐れ入りますが、こちらの資料を総務へ提出していただけますか。 4、提出して差し上げますか。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q14","part":1,"section":2,"type":"listening_response","prompt":"","options":["それでいいです。","社内で検討のうえ、改めてご回答させていただければと思います。","たぶん無理です。","後で決めます。"],"answer":2,"b":0.4,"explanation":"保留し再回答を約束する②。","audioText":"取引先の提案にその場で結論を出せない場面です。 最も適切なのはどれですか。 1、それでいいです。 2、社内で検討のうえ、改めてご回答させていただければと思います。 3、たぶん無理です。 4、後で決めます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S2-Q15","part":1,"section":2,"type":"listening_response","prompt":"","options":["何を飲みますか。","お飲み物はいかがなさいますか。","飲んでいただきますか。","お茶を飲まれます。"],"answer":2,"b":0.5,"explanation":"来客の選択を丁寧に尋ねる②。","audioText":"来客に飲み物を勧める場面です。 最も適切なのはどれですか。 1、何を飲みますか。 2、お飲み物はいかがなさいますか。 3、飲んでいただきますか。 4、お茶を飲まれます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M02-P1-S3-Q16","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["展示会に出展する","オンライン説明会を行う","広告を中止する","店舗を開く"],"answer":2,"b":-0.1,"explanation":"費用を抑えてオンライン説明会を先行。","audioText":"女：来月の展示会、出展費が80万円です。男：高いな。オンライン説明会なら20万円でできます。女：ただ、新規客との接点は減ります。男：今回は費用を抑えて、まずオンラインで反応を見よう。 最初に何をすることにしましたか。 1、展示会に出展する。 2、オンライン説明会を行う。 3、広告を中止する。 4、店舗を開く。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"販促方法"}},{"id":"M02-P1-S3-Q17","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["30個","50個","80個","150個"],"answer":2,"b":-0.5,"explanation":"来週分は50個。","audioText":"男：注文は200個でしたよね。女：はい。ただし50個は来週、残り150個は月末希望です。男：倉庫在庫は80個だから、来週50個は問題ない。残りは生産に回そう。 来週納品する数量はいくつですか。 1、30個。 2、50個。 3、80個。 4、150個。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"分納"}},{"id":"M02-P1-S3-Q18","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["A","B","両方","どちらも進まない"],"answer":2,"b":-0.3,"explanation":"必須条件の英語を満たすB。","audioText":"女：候補者Aは経験5年、Bは経験2年ですが英語が堪能です。男：今回の海外案件は英語対応が必須だ。女：ではBさんを二次面接へ進めます。 二次面接へ進むのは誰ですか。 1、A。 2、B。 3、両方。 4、どちらも進まない。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"採用"}},{"id":"M02-P1-S3-Q19","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["今日中","明日朝8時","明日10時まで","来週"],"answer":3,"b":-0.3,"explanation":"最終版は明日10時まで。","audioText":"男：会議資料は今日中に完成できますか。女：本文はできますが、売上データが明日の朝に確定します。男：では本文だけ今日共有して、最終版は明日10時までに。 最終版はいつ共有しますか。 1、今日中。 2、明日朝8時。 3、明日10時まで。 4、来週。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"資料提出"}},{"id":"M02-P1-S3-Q20","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["A便","B便","どちらでもよい","訪問を延期"],"answer":1,"b":-0.4,"explanation":"余裕をみてA便。","audioText":"女：A便は8時発で10時着、B便は9時発で10時半着です。男：11時から顧客訪問だからB便でも間に合うが、遅延が心配だ。女：ではA便にしましょう。 どの便を予約しますか。 1、A便。 2、B便。 3、どちらでもよい。 4、訪問を延期。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"出張"}},{"id":"M02-P1-S3-Q21","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["SNSだけ20万円削減","雑誌だけ20万円削減","SNSと雑誌を各10万円削減","予算を増額"],"answer":3,"b":0.0,"explanation":"各10万円、合計20万円削減。","audioText":"男：今月の広告費は予算を20万円超えています。女：SNS広告を10万円削減し、雑誌広告も10万円減らせます。男：では両方調整して予算内に戻そう。 どのように対応しますか。 1、SNSだけ20万円削減。 2、雑誌だけ20万円削減。 3、SNSと雑誌を各10万円削減。 4、予算を増額。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"予算"}},{"id":"M02-P1-S3-Q22","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["原因も確定済み","復旧済みで原因は調査中","まだ復旧していない","2日間停止する"],"answer":2,"b":0.1,"explanation":"復旧と原因未確定を分けて説明。","audioText":"女：システム障害は復旧しましたが、原因調査にはあと2日かかります。男：顧客には復旧済みと伝え、原因は調査中だと説明してください。 顧客に何を伝えますか。 1、原因も確定済み。 2、復旧済みで原因は調査中。 3、まだ復旧していない。 4、2日間停止する。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"障害対応"}},{"id":"M02-P1-S3-Q23","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["4,000円","4,500円","5,000円","5,500円"],"answer":2,"b":-0.2,"explanation":"5000円の10%引きで4500円。","audioText":"男：新商品は通常5,000円ですが、初回注文50個以上なら10％引きです。女：取引先は60個希望です。男：では4,500円で見積もって。 1個あたりの価格はいくらですか。 1、4,000円。 2、4,500円。 3、5,000円。 4、5,500円。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"見積"}},{"id":"M02-P1-S3-Q24","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["月曜午前","月曜午後","水曜午前","水曜午後"],"answer":3,"b":-0.5,"explanation":"水曜午前なら会議前。","audioText":"女：研修は月曜と水曜があります。男：月曜は出張で、水曜は午後会議です。女：研修は午前9時から11時です。男：それなら水曜に参加します。 いつ研修に参加しますか。 1、月曜午前。 2、月曜午後。 3、水曜午前。 4、水曜午後。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"研修日程"}},{"id":"M02-P1-S3-Q25","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["全商品値下げ","該当ロットの出荷停止と調査","広告を増やす","返品を受け付けない"],"answer":2,"b":0.2,"explanation":"問題ロットを止めて調査。","audioText":"男：返品率が先月3％から今月7％に上がっています。女：特定ロットに集中しています。男：そのロットの出荷を止め、品質部に調査を依頼しよう。 最初に行うことは何ですか。 1、全商品値下げ。 2、該当ロットの出荷停止と調査。 3、広告を増やす。 4、返品を受け付けない。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"品質管理"}},{"id":"M02-P2-S1-Q26","part":2,"section":1,"type":"listen_read_situation","prompt":"どの会議室を使えますか。","options":["Aのみ","Bのみ","AとBの両方","どちらも不可"],"answer":3,"b":-0.6,"explanation":"15時ならAも空き、Bも空き。","audioText":"担当：今日の午後、A会議室は14時まで使用中です。B会議室は終日空いています。15時から8名で打ち合わせをします。","visual":{"kind":"table","title":"会議室","headers":["会議室","使用状況","定員"],"rows":[["A","～14:00使用","10"],["B","空き","8"]]}},{"id":"M02-P2-S1-Q27","part":2,"section":1,"type":"listen_read_situation","prompt":"条件を満たす業者はどれですか。","options":["A社","B社","C社","D社"],"answer":2,"b":0.0,"explanation":"B社は価格9.5万円・4日。","audioText":"担当：予算は10万円以内、納期は5日以内が条件です。","visual":{"kind":"table","title":"見積","headers":["会社","価格","納期"],"rows":[["A","8万円","7日"],["B","9.5万円","4日"],["C","11万円","3日"],["D","10.5万円","5日"]]}},{"id":"M02-P2-S1-Q28","part":2,"section":1,"type":"listen_read_situation","prompt":"面談可能なのはいつですか。","options":["11:30","12:00","13:00","14:30"],"answer":3,"b":-0.7,"explanation":"13時のみ空き。","audioText":"秘書：部長は11時から12時まで会議、14時から外出です。13時なら空いています。","visual":{"kind":"table","title":"部長予定","headers":["時間","予定"],"rows":[["11:00-12:00","会議"],["13:00","空き"],["14:00-","外出"]]}},{"id":"M02-P2-S1-Q29","part":2,"section":1,"type":"listen_read_situation","prompt":"誰の承認が必要ですか。","options":["主任","課長","部長","社長"],"answer":3,"b":-0.4,"explanation":"8万円は部長承認。","audioText":"総務：申請額が3万円未満なら課長承認、3万円以上10万円未満なら部長承認です。今回の申請は8万円です。","visual":{"kind":"note","title":"承認基準","lines":["3万円未満：課長","3万～10万円未満：部長","10万円以上：役員"]}},{"id":"M02-P2-S1-Q30","part":2,"section":1,"type":"listen_read_situation","prompt":"どちらを選びますか。","options":["新幹線","飛行機","同じ","出張中止"],"answer":1,"b":-0.7,"explanation":"時間優先なので2時間の新幹線。","audioText":"担当：新幹線なら2時間、飛行機なら空港移動込みで3時間です。費用は新幹線12,000円、飛行機10,000円です。今日は時間を優先します。","visual":{"kind":"table","title":"移動比較","headers":["手段","所要","費用"],"rows":[["新幹線","2時間","12,000円"],["飛行機","3時間","10,000円"]]}},{"id":"M02-P2-S2-Q31","part":2,"section":2,"type":"listen_read_data","prompt":"最も適切な説明はどれですか。","options":["売上も利益率も上昇","売上は上昇、利益率は低下","売上は低下、利益率は上昇","両方変化なし"],"answer":2,"b":-0.4,"explanation":"音声と表の傾向が一致する②。","audioText":"担当：売上は前年比で増えていますが、利益率は下がっています。","visual":{"kind":"table","title":"業績","headers":["項目","前年","今年"],"rows":[["売上","100","112"],["利益率","18%","14%"]]}},{"id":"M02-P2-S2-Q32","part":2,"section":2,"type":"listen_read_data","prompt":"対象商品はどれですか。","options":["A","B","C","D"],"answer":4,"b":0.1,"explanation":"Dが最短12日。","audioText":"担当：在庫回転日数が最も短い商品を重点販売します。","visual":{"kind":"table","title":"在庫回転日数","headers":["商品","日数"],"rows":[["A","25"],["B","18"],["C","31"],["D","12"]]}},{"id":"M02-P2-S2-Q33","part":2,"section":2,"type":"listen_read_data","prompt":"改善対象はいくつありますか。","options":["1","2","3","4"],"answer":3,"b":-0.2,"explanation":"価格65、納期68、サポート62の3項目。","audioText":"上司：顧客満足度が70％未満の項目を改善対象にします。","visual":{"kind":"table","title":"満足度","headers":["項目","満足度"],"rows":[["品質","84%"],["価格","65%"],["納期","68%"],["サポート","62%"]]}},{"id":"M02-P2-S2-Q34","part":2,"section":2,"type":"listen_read_data","prompt":"損益分岐点数量はいくつですか。","options":["100個","150個","200個","300個"],"answer":3,"b":0.8,"explanation":"60万円÷3000円=200個。","audioText":"経理：固定費は60万円、1個あたりの限界利益は3,000円です。","visual":{"kind":"note","title":"損益分岐点","lines":["固定費：600,000円","限界利益：3,000円／個"]}},{"id":"M02-P2-S2-Q35","part":2,"section":2,"type":"listen_read_data","prompt":"利用できる経路はどれですか。","options":["A","B","C","D"],"answer":2,"b":0.3,"explanation":"Bは13:40着、乗換1回。","audioText":"担当：午後2時までに到着し、乗り換えは1回までにしたいです。","visual":{"kind":"table","title":"経路","headers":["経路","到着","乗換"],"rows":[["A","13:50","2回"],["B","13:40","1回"],["C","14:10","0回"],["D","13:20","3回"]]}},{"id":"M02-P2-S2-Q36","part":2,"section":2,"type":"listen_read_data","prompt":"対象部署はどれですか。","options":["営業だけ","開発だけ","営業と開発","全部署"],"answer":3,"b":-0.3,"explanation":"営業24、開発31が対象。","audioText":"人事：残業時間が月20時間を超えた部署に面談を実施します。","visual":{"kind":"table","title":"平均残業時間","headers":["部署","時間"],"rows":[["営業","24"],["総務","12"],["開発","31"],["経理","18"]]}},{"id":"M02-P2-S2-Q37","part":2,"section":2,"type":"listen_read_data","prompt":"どのプランですか。","options":["ライト","スタンダード","プロ","どれも不可"],"answer":2,"b":-0.1,"explanation":"スタンダードは5万円・60人。","audioText":"担当：月額費用が5万円以下で、利用人数50人以上に対応するプランを選びます。","visual":{"kind":"table","title":"プラン","headers":["プラン","月額","人数"],"rows":[["ライト","3万円","30"],["スタンダード","5万円","60"],["プロ","8万円","100"]]}},{"id":"M02-P2-S2-Q38","part":2,"section":2,"type":"listen_read_data","prompt":"どの部署ですか。","options":["A","B","C","D"],"answer":1,"b":0.0,"explanation":"Aは5%→2%で3pt改善、最大。","audioText":"上司：欠勤率が最も改善した部署を表彰します。","visual":{"kind":"table","title":"欠勤率","headers":["部署","前年","今年"],"rows":[["A","5%","2%"],["B","4%","3%"],["C","3%","3%"],["D","6%","5%"]]}},{"id":"M02-P2-S2-Q39","part":2,"section":2,"type":"listen_read_data","prompt":"どの商品ですか。","options":["A","B","C","D"],"answer":3,"b":0.9,"explanation":"C=200×25%=50で最大。","audioText":"担当：粗利額が最も大きい商品を重点商品にします。粗利額は売上×粗利率です。","visual":{"kind":"table","title":"商品別","headers":["商品","売上(万円)","粗利率"],"rows":[["A","120","30%"],["B","160","20%"],["C","200","25%"],["D","100","40%"]]}},{"id":"M02-P2-S2-Q40","part":2,"section":2,"type":"listen_read_data","prompt":"督促対象はどれですか。","options":["A","B","C","D"],"answer":1,"b":-0.5,"explanation":"Aの期限9/18だけ超過。","audioText":"総務：申請期限を過ぎているものだけ督促します。今日は9月20日です。","visual":{"kind":"table","title":"申請","headers":["案件","期限"],"rows":[["A","9/18"],["B","9/20"],["C","9/22"],["D","9/25"]]}},{"id":"M02-P2-S3-Q41","part":2,"section":3,"type":"listen_read_dialogue","prompt":"表彰されるのはどこですか。","options":["A","B","C","D"],"answer":2,"b":-0.2,"explanation":"品質管理基準なので返品率最低のB。","audioText":"部長：支店Aは売上が高いが返品率も高い。支店Bは売上は少し低いが返品率が最も低い。今回は品質管理の優秀店を表彰します。","visual":{"kind":"table","title":"支店実績","headers":["支店","売上","返品率"],"rows":[["A","120","5%"],["B","110","1%"],["C","95","3%"],["D","105","2%"]]}},{"id":"M02-P2-S3-Q42","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どの企画を選びますか。","options":["A","B","C","D"],"answer":4,"b":0.2,"explanation":"30万円以内で効果最大のD。","audioText":"担当：企画Aは費用が高いですが効果も大きい。企画Bは低費用ですが効果が小さいです。今回は予算上限30万円で効果が最大の案を選びます。","visual":{"kind":"table","title":"企画比較","headers":["案","費用","効果"],"rows":[["A","45万","90"],["B","15万","45"],["C","25万","60"],["D","30万","75"]]}},{"id":"M02-P2-S3-Q43","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どこに増員しますか。","options":["電話","メール","チャット","窓口"],"answer":3,"b":-0.6,"explanation":"最多120件のチャット。","audioText":"上司：今週の問い合わせは電話が40件、メールが80件、チャットが120件でした。来週は最も多いチャネルに人員を1名増やします。","visual":{"kind":"table","title":"問い合わせ","headers":["チャネル","件数"],"rows":[["電話","40"],["メール","80"],["チャット","120"]]}},{"id":"M02-P2-S3-Q44","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どの候補地が最適ですか。","options":["A","B","C","D"],"answer":2,"b":0.4,"explanation":"駅距離最短のB。","audioText":"担当：この候補地は駅から近いことを最優先し、次に賃料を見ます。","visual":{"kind":"table","title":"候補地","headers":["候補","駅徒歩","賃料"],"rows":[["A","5分","40万"],["B","2分","48万"],["C","8分","32万"],["D","4分","55万"]]}},{"id":"M02-P2-S3-Q45","part":2,"section":3,"type":"listen_read_dialogue","prompt":"3年総額が安いのはどちらですか。","options":["A社","B社","同額","不明"],"answer":2,"b":0.8,"explanation":"A=10+2×36=82、B=25+1.2×36=68.2。","audioText":"男：A社は初期費用が安いですが月額が高い。女：B社は初期費用が高くても月額が低いですね。3年間使うので総額で比べましょう。","visual":{"kind":"table","title":"クラウド費用(万円)","headers":["会社","初期","月額"],"rows":[["A","10","2.0"],["B","25","1.2"]]}},{"id":"M02-P2-S3-Q46","part":2,"section":3,"type":"listen_read_dialogue","prompt":"継続対象はいくつですか。","options":["1社","2社","3社","4社"],"answer":2,"b":0.1,"explanation":"AとDの2社。","audioText":"担当：納期遵守率90％以上、かつ不良率2％以下の仕入先だけ継続します。","visual":{"kind":"table","title":"仕入先評価","headers":["社","納期遵守","不良率"],"rows":[["A","95%","1%"],["B","88%","1%"],["C","93%","3%"],["D","91%","2%"]]}},{"id":"M02-P2-S3-Q47","part":2,"section":3,"type":"listen_read_dialogue","prompt":"B社には何時に着けますか。","options":["11:30","12:00","12:15","12:30"],"answer":3,"b":0.3,"explanation":"11時出発＋30分移動＋45分昼食=12:15。","audioText":"秘書：A社訪問は10時から1時間、A社からB社までは30分です。B社は12時から面談可能です。途中で昼食を45分取りたいです。","visual":{"kind":"route","title":"訪問予定","lines":["A社 10:00–11:00","A→B 30分","昼食 45分","B社 12:00以降可"]}},{"id":"M02-P2-S3-Q48","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どう対応しますか。","options":["2人で営業","木村のシフトを夕方へ変更","閉店する","新規採用"],"answer":2,"b":-0.5,"explanation":"不足1名をシフト変更で補う。","audioText":"店長：平日夕方は最低3人必要です。火曜は2人しかいません。木村さんは火曜午前から夕方へ変更可能です。","visual":{"kind":"table","title":"火曜シフト","headers":["時間","必要","現在"],"rows":[["午前","2","3"],["夕方","3","2"]]}},{"id":"M02-P2-S3-Q49","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どちらを選びますか。","options":["A社","B社","両方","どちらも不可"],"answer":1,"b":0.2,"explanation":"両社納期条件を満たし、保証が長いA。","audioText":"担当：今回の機器は10日以内の納入が必須です。A社は7日、B社は5日ですが、A社は保証3年、B社は1年です。価格差は小さいので保証も重視します。","visual":{"kind":"table","title":"比較","headers":["会社","納期","保証"],"rows":[["A","7日","3年"],["B","5日","1年"]]}},{"id":"M02-P2-S3-Q50","part":2,"section":3,"type":"listen_read_dialogue","prompt":"最優先はどれですか。","options":["備品不足","軽微な誤字","サーバ停止","会議遅延"],"answer":3,"b":0.7,"explanation":"影響極大のサーバ停止。","audioText":"責任者：発生確率が中でも影響が極めて大きいサーバ停止は優先対策します。","visual":{"kind":"table","title":"リスク","headers":["項目","確率","影響"],"rows":[["備品不足","高","小"],["誤字","高","小"],["サーバ停止","中","極大"],["会議遅延","中","中"]]}},{"id":"M02-P3-S1-Q51","part":3,"section":1,"type":"reading_vocab","prompt":"売上減少の原因を＿＿ため、顧客への聞き取りを行った。","options":["見極める","見送る","見計らう","見かける"],"answer":1,"b":0.3,"explanation":"原因を正確に判断する＝見極める。"},{"id":"M02-P3-S1-Q52","part":3,"section":1,"type":"reading_vocab","prompt":"この制度は全社員＿＿適用されます。","options":["に対して","に沿って","に先立って","に比べて"],"answer":1,"b":-0.1,"explanation":"対象を示す「～に対して」。"},{"id":"M02-P3-S1-Q53","part":3,"section":1,"type":"reading_vocab","prompt":"交渉の結果、価格を下げ＿＿品質を維持することで合意した。","options":["ながら","つつ","ものの","まで"],"answer":1,"b":0.4,"explanation":"同時並行・両立を表す。"},{"id":"M02-P3-S1-Q54","part":3,"section":1,"type":"reading_vocab","prompt":"事情は理解できるが、規則上認め＿＿。","options":["ないことはない","ざるを得ない","るわけにはいかない","に違いない"],"answer":3,"b":0.8,"explanation":"立場上できない＝わけにはいかない。"},{"id":"M02-P3-S1-Q55","part":3,"section":1,"type":"reading_vocab","prompt":"新サービスは来月開始する＿＿です。","options":["予定","目当て","見当","手間"],"answer":1,"b":-0.4,"explanation":"計画された未来＝予定。"},{"id":"M02-P3-S1-Q56","part":3,"section":1,"type":"reading_vocab","prompt":"詳細が決まり＿＿、改めてご連絡いたします。","options":["次第","限り","際","末"],"answer":1,"b":0.2,"explanation":"決まり次第＝決まったらすぐ。"},{"id":"M02-P3-S1-Q57","part":3,"section":1,"type":"reading_vocab","prompt":"この件については、現時点では回答を＿＿ください。","options":["差し控えて","遠慮して","見送って","断って"],"answer":1,"b":0.6,"explanation":"公的に回答を控える＝差し控える。"},{"id":"M02-P3-S1-Q58","part":3,"section":1,"type":"reading_vocab","prompt":"会議では各部署の意見を＿＿うえで、最終案を決める。","options":["踏まえた","備えた","構えた","控えた"],"answer":1,"b":0.7,"explanation":"～を踏まえる＝考慮する。"},{"id":"M02-P3-S1-Q59","part":3,"section":1,"type":"reading_vocab","prompt":"予算の範囲内で＿＿多くの機能を実装したい。","options":["なるべく","あらかじめ","いずれ","さっぱり"],"answer":1,"b":-0.3,"explanation":"可能な限り＝なるべく。"},{"id":"M02-P3-S1-Q60","part":3,"section":1,"type":"reading_vocab","prompt":"先方の要望に＿＿形で仕様を変更した。","options":["沿う","向く","応じる","限る"],"answer":1,"b":0.5,"explanation":"要望に沿う＝要望に合致する。"},{"id":"M02-P3-S2-Q61","part":3,"section":2,"type":"reading_expression","prompt":"取引先へ確認を依頼するメールとして最も適切なのはどれですか。","options":["確認して。","お手数をおかけしますが、添付資料をご確認いただけますでしょうか。","資料を見られますか。","確認していただきます。"],"answer":2,"b":-0.3,"explanation":"配慮＋丁寧な依頼。"},{"id":"M02-P3-S2-Q62","part":3,"section":2,"type":"reading_expression","prompt":"上司の説明が聞き取れなかったとき最も適切なのはどれですか。","options":["もう一回。","恐れ入りますが、最後の点をもう一度ご説明いただけますか。","聞こえません。","何を言いましたか。"],"answer":2,"b":-0.1,"explanation":"丁寧な再説明依頼。"},{"id":"M02-P3-S2-Q63","part":3,"section":2,"type":"reading_expression","prompt":"顧客から値下げを求められ、その場では判断できないとき最も適切なのはどれですか。","options":["無理です。","社内で検討のうえ、改めてご回答いたします。","安くします。","分かりません。"],"answer":2,"b":-0.4,"explanation":"即答せず検討後回答。"},{"id":"M02-P3-S2-Q64","part":3,"section":2,"type":"reading_expression","prompt":"社内会議で他部署の協力を求める表現として最も適切なのはどれですか。","options":["協力してください。","ご協力いただけますと大変助かります。","協力してあげてください。","協力なさいます。"],"answer":2,"b":0.0,"explanation":"丁寧な協力依頼。"},{"id":"M02-P3-S2-Q65","part":3,"section":2,"type":"reading_expression","prompt":"来客に待ってもらう表現として最も適切なのはどれですか。","options":["ここで待って。","こちらで少々お待ちいただけますでしょうか。","待たせます。","待ってあげます。"],"answer":2,"b":-0.2,"explanation":"来客への丁寧な依頼。"},{"id":"M02-P3-S2-Q66","part":3,"section":2,"type":"reading_expression","prompt":"顧客の名前を聞き直すとき最も適切なのはどれですか。","options":["名前は？","恐れ入りますが、もう一度お名前を頂戴してもよろしいでしょうか。","お名前を言って。","誰ですか。"],"answer":2,"b":0.1,"explanation":"聞き返しの配慮がある。"},{"id":"M02-P3-S2-Q67","part":3,"section":2,"type":"reading_expression","prompt":"資料に誤りがあったことを上司へ報告する文として最も適切なのはどれですか。","options":["資料が間違っていました。","私の確認不足で誤りがございました。申し訳ありません。修正版をすぐに提出いたします。","誰かが間違えました。","大した間違いではありません。"],"answer":2,"b":0.0,"explanation":"責任・謝罪・対応を明示。"},{"id":"M02-P3-S2-Q68","part":3,"section":2,"type":"reading_expression","prompt":"まだ確定していない納期を伝える表現として最も適切なのはどれですか。","options":["来週必ず納品します。","現時点では、来週後半の納品となる見込みです。","絶対来週です。","来週に違いありません。"],"answer":2,"b":0.1,"explanation":"未確定情報には見込み。"},{"id":"M02-P3-S2-Q69","part":3,"section":2,"type":"reading_expression","prompt":"部下が上司へ休暇を申請するとき最も適切なのはどれですか。","options":["金曜休みます。","恐れ入りますが、金曜日に休暇を取得させていただいてもよろしいでしょうか。","金曜は休ませます。","休んであげます。"],"answer":2,"b":0.2,"explanation":"許可を求める形。"},{"id":"M02-P3-S2-Q70","part":3,"section":2,"type":"reading_expression","prompt":"取引先からの電話を担当者へつなぐとき最も適切なのはどれですか。","options":["担当者に代わります。","ただいま担当の鈴木におつなぎいたします。少々お待ちください。","鈴木様を呼びます。","鈴木さんに替えてあげます。"],"answer":2,"b":-0.1,"explanation":"社内者を高めず丁寧に取次。"},{"id":"M02-P3-S3-Q71","part":3,"section":3,"type":"reading_comprehension","prompt":"予約できるのは利用日の何日前からですか。","options":["10日前","20日前","30日前","60日前"],"answer":3,"b":-0.6,"explanation":"30日前から。","passage":"【会議室予約ルール変更】\n10月1日から会議室予約は新システムへ移行する。予約は利用日の30日前から可能で、利用開始10分前までにチェックインしない場合は自動キャンセルとなる。外部来客を伴う場合は、予約時に来客人数を登録すること。なお、役員会議室の利用には総務部の事前承認が必要である。"},{"id":"M02-P3-S3-Q72","part":3,"section":3,"type":"reading_comprehension","prompt":"自動キャンセルとなる条件はどれですか。","options":["外部来客がいる","10分前までにチェックインしない","30日前に予約する","総務承認を得る"],"answer":2,"b":-0.4,"explanation":"10分前までのチェックインが必要。","passage":"【会議室予約ルール変更】\n10月1日から会議室予約は新システムへ移行する。予約は利用日の30日前から可能で、利用開始10分前までにチェックインしない場合は自動キャンセルとなる。外部来客を伴う場合は、予約時に来客人数を登録すること。なお、役員会議室の利用には総務部の事前承認が必要である。"},{"id":"M02-P3-S3-Q73","part":3,"section":3,"type":"reading_comprehension","prompt":"売上が減少した商品はどれですか。","options":["A","B","C","すべて増加"],"answer":3,"b":-0.7,"explanation":"Cのみ5%減。","passage":"【販売キャンペーン結果】\n春のキャンペーンでは、A商品は売上が前年同期比15％増、B商品は8％増、C商品は5％減となった。広告費はA商品が最も高かったが、新規顧客獲得数も最多だった。次回はA商品の広告費を維持しつつ、C商品は対象顧客を見直して小規模なテスト広告を行う。"},{"id":"M02-P3-S3-Q74","part":3,"section":3,"type":"reading_comprehension","prompt":"次回、C商品について何をしますか。","options":["広告を完全中止","大型広告を実施","対象顧客を見直し小規模テスト","価格を上げる"],"answer":3,"b":-0.2,"explanation":"本文最終文。","passage":"【販売キャンペーン結果】\n春のキャンペーンでは、A商品は売上が前年同期比15％増、B商品は8％増、C商品は5％減となった。広告費はA商品が最も高かったが、新規顧客獲得数も最多だった。次回はA商品の広告費を維持しつつ、C商品は対象顧客を見直して小規模なテスト広告を行う。"},{"id":"M02-P3-S3-Q75","part":3,"section":3,"type":"reading_comprehension","prompt":"共有アカウントについて正しいのはどれですか。","options":["部署内なら可","禁止されている","社外のみ可","上司承認で可"],"answer":2,"b":-0.5,"explanation":"共有アカウントは禁止。","passage":"【情報セキュリティ通知】\n社外からアクセスする場合は多要素認証を必須とする。共有アカウントの利用は禁止し、個人ごとのIDを使用すること。パスワードは90日ごとに変更する。ただし、認証アプリによるパスワードレス方式を利用する社員は定期変更の対象外とする。端末紛失時は、発見を待たず直ちに情報システム部へ連絡する。"},{"id":"M02-P3-S3-Q76","part":3,"section":3,"type":"reading_comprehension","prompt":"端末を紛失したときどうしますか。","options":["翌日連絡","見つかるまで待つ","直ちに情報システム部へ連絡","同僚だけに伝える"],"answer":3,"b":-0.6,"explanation":"直ちに連絡。","passage":"【情報セキュリティ通知】\n社外からアクセスする場合は多要素認証を必須とする。共有アカウントの利用は禁止し、個人ごとのIDを使用すること。パスワードは90日ごとに変更する。ただし、認証アプリによるパスワードレス方式を利用する社員は定期変更の対象外とする。端末紛失時は、発見を待たず直ちに情報システム部へ連絡する。"},{"id":"M02-P3-S3-Q77","part":3,"section":3,"type":"reading_comprehension","prompt":"優先して行うのは何ですか。","options":["Bを量産","Aの部品構成見直し","Aを中止","予算を20%増額"],"answer":2,"b":0.0,"explanation":"Aのコスト低減を優先。","passage":"【新製品開発メモ】\n試作品Aは性能目標を満たしたが製造コストが予算を20％上回った。試作品Bは予算内だが耐久性試験で基準を満たさなかった。開発チームは、Aの部品構成を見直してコストを下げる案を優先し、2週間後に再試作する。Bについては材料変更の可能性を並行して調査する。"},{"id":"M02-P3-S3-Q78","part":3,"section":3,"type":"reading_comprehension","prompt":"Bについて何をしますか。","options":["何もしない","量産開始","材料変更の可能性を調査","価格を下げる"],"answer":3,"b":0.0,"explanation":"並行して材料変更を調査。","passage":"【新製品開発メモ】\n試作品Aは性能目標を満たしたが製造コストが予算を20％上回った。試作品Bは予算内だが耐久性試験で基準を満たさなかった。開発チームは、Aの部品構成を見直してコストを下げる案を優先し、2週間後に再試作する。Bについては材料変更の可能性を並行して調査する。"},{"id":"M02-P3-S3-Q79","part":3,"section":3,"type":"reading_comprehension","prompt":"研修には何回参加する必要がありますか。","options":["両方","どちらか1回","3回","参加不要"],"answer":2,"b":-0.7,"explanation":"内容同一でいずれか1回。","passage":"【研修参加案内】\n管理職向け研修は11月12日と14日の2回開催する。内容は同一で、いずれか1回に参加すればよい。各回定員40名で先着順。申込後の回変更は、変更先に空席がある場合に限り11月5日まで受け付ける。欠席する場合は代理参加を認めるが、事前に人事部へ連絡すること。"},{"id":"M02-P3-S3-Q80","part":3,"section":3,"type":"reading_comprehension","prompt":"回の変更ができる条件はどれですか。","options":["いつでも可能","11月5日までで変更先に空席がある","定員を超えても可","当日でも可"],"answer":2,"b":-0.2,"explanation":"期限＋空席条件。","passage":"【研修参加案内】\n管理職向け研修は11月12日と14日の2回開催する。内容は同一で、いずれか1回に参加すればよい。各回定員40名で先着順。申込後の回変更は、変更先に空席がある場合に限り11月5日まで受け付ける。欠席する場合は代理参加を認めるが、事前に人事部へ連絡すること。"}]},"BJT-MOCK-03":{"id":"BJT-MOCK-03","code":"MOCK 03","title":"模擬試驗 第3回","questions":[{"id":"M03-P1-S1-Q01","part":1,"section":1,"type":"listening_scene","prompt":"","options":["男性が宅配便に荷物を渡しています。","男性が顧客に商品を説明しています。","男性が机を組み立てています。","男性が電話会議をしています。"],"answer":1,"b":-0.9,"explanation":"荷物を配送担当へ渡す場面。","audioText":"1、男性が宅配便に荷物を渡しています。 2、男性が顧客に商品を説明しています。 3、男性が机を組み立てています。 4、男性が電話会議をしています。","visual":{"kind":"emoji","scene":"🧑‍💼 📦➡️ 🚚","sub":"発送"}},{"id":"M03-P1-S1-Q02","part":1,"section":1,"type":"listening_scene","prompt":"","options":["女性が会議の議事録を配っています。","女性がパソコンを修理しています。","女性が棚卸しをしています。","女性が食事を注文しています。"],"answer":1,"b":-0.8,"explanation":"会議参加者へ紙を配布している。","audioText":"1、女性が会議の議事録を配っています。 2、女性がパソコンを修理しています。 3、女性が棚卸しをしています。 4、女性が食事を注文しています。","visual":{"kind":"emoji","scene":"👩‍💼 📄➡️ 👥","sub":"会議"}},{"id":"M03-P1-S1-Q03","part":1,"section":1,"type":"listening_scene","prompt":"","options":["二人が商品サンプルを確認しています。","二人が駅の時刻表を見ています。","二人が採用面接をしています。","二人が電話を交換しています。"],"answer":1,"b":-0.8,"explanation":"商品サンプルを手に確認する場面。","audioText":"1、二人が商品サンプルを確認しています。 2、二人が駅の時刻表を見ています。 3、二人が採用面接をしています。 4、二人が電話を交換しています。","visual":{"kind":"emoji","scene":"👥 🔍 📦","sub":"商品確認"}},{"id":"M03-P1-S1-Q04","part":1,"section":1,"type":"listening_scene","prompt":"","options":["受付係が来客に入館証を渡しています。","受付係が書類を破棄しています。","受付係が商品を販売しています。","受付係が会議を司会しています。"],"answer":1,"b":-1.0,"explanation":"受付で入館証を手渡す。","audioText":"1、受付係が来客に入館証を渡しています。 2、受付係が書類を破棄しています。 3、受付係が商品を販売しています。 4、受付係が会議を司会しています。","visual":{"kind":"emoji","scene":"👩‍💼 🪪➡️ 👨‍💼","sub":"受付"}},{"id":"M03-P1-S1-Q05","part":1,"section":1,"type":"listening_scene","prompt":"","options":["社員がプリンターに紙を補充しています。","社員が契約書に押印しています。","社員が来客を見送っています。","社員が荷物を計量しています。"],"answer":1,"b":-0.9,"explanation":"プリンターへ用紙を補充。","audioText":"1、社員がプリンターに紙を補充しています。 2、社員が契約書に押印しています。 3、社員が来客を見送っています。 4、社員が荷物を計量しています。","visual":{"kind":"emoji","scene":"🧑‍💼 📄➡️ 🖨️","sub":"オフィス"}},{"id":"M03-P1-S2-Q06","part":1,"section":2,"type":"listening_response","prompt":"","options":["担当が変わります。","このたび担当が山田から私、佐藤に変更となりました。今後ともよろしくお願い申し上げます。","山田はもう担当しません。","私が担当してあげます。"],"answer":2,"b":0.0,"explanation":"正式な担当変更通知として②。","audioText":"顧客に担当変更を知らせる場面です。 最も適切なのはどれですか。 1、担当が変わります。 2、このたび担当が山田から私、佐藤に変更となりました。今後ともよろしくお願い申し上げます。 3、山田はもう担当しません。 4、私が担当してあげます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q07","part":1,"section":2,"type":"listening_response","prompt":"","options":["これ見てください。","お忙しいところ恐れ入りますが、会議資料をご確認いただけますでしょうか。","資料をご覧になってあげますか。","確認なさっていただきます。"],"answer":2,"b":0.2,"explanation":"配慮ある確認依頼。","audioText":"上司に会議資料の確認をお願いする場面です。 最も適切なのはどれですか。 1、これ見てください。 2、お忙しいところ恐れ入りますが、会議資料をご確認いただけますでしょうか。 3、資料をご覧になってあげますか。 4、確認なさっていただきます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q08","part":1,"section":2,"type":"listening_response","prompt":"","options":["ありません。","あると思います。","ただいま在庫を確認いたしますので、少々お待ちいただけますでしょうか。","わかりません。"],"answer":3,"b":-0.2,"explanation":"未確認なので確認を約束する③。","audioText":"顧客から商品の在庫を聞かれ、まだ確認できていません。 最も適切なのはどれですか。 1、ありません。 2、あると思います。 3、ただいま在庫を確認いたしますので、少々お待ちいただけますでしょうか。 4、わかりません。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q09","part":1,"section":2,"type":"listening_response","prompt":"","options":["時間を変えます。","大変恐縮ですが、訪問時間を15時から16時に変更させていただくことは可能でしょうか。","16時にしてください。","15時は行けません。"],"answer":2,"b":0.2,"explanation":"こちら都合の変更を丁寧に依頼。","audioText":"取引先に訪問時間の変更をお願いする場面です。 最も適切なのはどれですか。 1、時間を変えます。 2、大変恐縮ですが、訪問時間を15時から16時に変更させていただくことは可能でしょうか。 3、16時にしてください。 4、15時は行けません。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q10","part":1,"section":2,"type":"listening_response","prompt":"","options":["了解です。","承知いたしました。","ご理解しました。","わかってあげました。"],"answer":2,"b":-0.4,"explanation":"上司への返答として②。","audioText":"部下が上司から説明を受け、理解したことを示します。 最も適切なのはどれですか。 1、了解です。 2、承知いたしました。 3、ご理解しました。 4、わかってあげました。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q11","part":1,"section":2,"type":"listening_response","prompt":"","options":["いつ電話すればいい？","何時ごろお電話を差し上げればよろしいでしょうか。","何時に電話させますか。","電話してほしい時間は？"],"answer":2,"b":0.3,"explanation":"丁寧に都合を尋ねる②。","audioText":"顧客に折り返し電話する時間を尋ねます。 最も適切なのはどれですか。 1、いつ電話すればいい？ 2、何時ごろお電話を差し上げればよろしいでしょうか。 3、何時に電話させますか。 4、電話してほしい時間は？","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q12","part":1,"section":2,"type":"listening_response","prompt":"","options":["それはお客様の勘違いです。","ご不快な思いをおかけし申し訳ございません。まず状況を確認させていただけますでしょうか。","担当ではありません。","返品してください。"],"answer":2,"b":0.4,"explanation":"謝罪＋事実確認。","audioText":"クレーム対応で、まず事実確認が必要です。 最も適切なのはどれですか。 1、それはお客様の勘違いです。 2、ご不快な思いをおかけし申し訳ございません。まず状況を確認させていただけますでしょうか。 3、担当ではありません。 4、返品してください。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q13","part":1,"section":2,"type":"listening_response","prompt":"","options":["これ、どうぞ。","こちらが先ほどお話しした資料でございます。ご査収ください。","資料を見てあげてください。","この資料をもらってください。"],"answer":2,"b":0.4,"explanation":"社外への丁寧な提示。","audioText":"訪問先で資料を渡す場面です。 最も適切なのはどれですか。 1、これ、どうぞ。 2、こちらが先ほどお話しした資料でございます。ご査収ください。 3、資料を見てあげてください。 4、この資料をもらってください。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q14","part":1,"section":2,"type":"listening_response","prompt":"","options":["つまり、納期を一週間延ばすということでよろしいでしょうか。","納期を延ばすんですね。","何が言いたいですか。","延ばしてあげますか。"],"answer":1,"b":0.3,"explanation":"要点を復唱確認。","audioText":"会議で発言者の意図を確認します。 最も適切なのはどれですか。 1、つまり、納期を一週間延ばすということでよろしいでしょうか。 2、納期を延ばすんですね。 3、何が言いたいですか。 4、延ばしてあげますか。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S2-Q15","part":1,"section":2,"type":"listening_response","prompt":"","options":["今日休みます。","大変申し訳ありませんが、体調不良のため本日は休ませていただきたく、ご連絡いたしました。","今日は無理です。","休んであげます。"],"answer":2,"b":0.2,"explanation":"謝罪＋理由＋意向。","audioText":"上司に急な欠勤を連絡する場面です。 最も適切なのはどれですか。 1、今日休みます。 2、大変申し訳ありませんが、体調不良のため本日は休ませていただきたく、ご連絡いたしました。 3、今日は無理です。 4、休んであげます。","visual":{"kind":"emoji","scene":"👥 💬","sub":"ビジネス場面"}},{"id":"M03-P1-S3-Q16","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["30部","35部","40部","45部"],"answer":3,"b":-0.6,"explanation":"35+5=40部。","audioText":"女：来週の顧客説明会、資料は何部必要ですか。男：参加予定は35名ですが、予備を5部用意しましょう。 何部印刷しますか。 1、30部。 2、35部。 3、40部。 4、45部。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"資料準備"}},{"id":"M03-P1-S3-Q17","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["A社","B社","同額","未定"],"answer":1,"b":0.1,"explanation":"総額A120、B125。","audioText":"男：A社の見積は120万円、B社は110万円です。女：ただしB社は設置費15万円が別です。男：それなら総額ではA社の方が安いね。 どちらを選ぶ方向ですか。 1、A社。 2、B社。 3、同額。 4、未定。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"見積比較"}},{"id":"M03-P1-S3-Q18","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["水曜","木曜","金曜","土曜"],"answer":2,"b":-0.4,"explanation":"木曜出荷。","audioText":"女：商品の到着は金曜予定でしたが、倉庫から木曜に出せるそうです。男：顧客が金曜午前に必要だから、木曜出荷で間に合うね。 商品はいつ出荷しますか。 1、水曜。 2、木曜。 3、金曜。 4、土曜。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"物流"}},{"id":"M03-P1-S3-Q19","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["1日目だけ","2日目だけ","1日目と3日目","3日間全部"],"answer":3,"b":-0.1,"explanation":"1日目と3日目。","audioText":"男：新人研修は3日間ですが、初日は全員必須です。女：私は2日目に顧客訪問があります。男：初日と3日目に参加して、2日目分は動画で補ってください。 女性はどの日に会場参加しますか。 1、1日目だけ。 2、2日目だけ。 3、1日目と3日目。 4、3日間全部。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"研修"}},{"id":"M03-P1-S3-Q20","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["10万円","20万円","30万円","80万円"],"answer":1,"b":0.2,"explanation":"420+60+30=510、10万円超過。","audioText":"女：今月の売上目標は500万円で、現在420万円です。男：残り80万円か。大型案件が60万円、通常受注で30万円見込める。 見込み通りなら目標をいくら上回りますか。 1、10万円。 2、20万円。 3、30万円。 4、80万円。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"売上目標"}},{"id":"M03-P1-S3-Q21","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["13:00","13:15","13:30","14:00"],"answer":3,"b":-0.6,"explanation":"13時半。","audioText":"男：会議は13時開始でしたが、部長の到着が30分遅れます。女：参加者には13時半開始と連絡します。 会議開始は何時ですか。 1、13:00。 2、13:15。 3、13:30。 4、14:00。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"会議変更"}},{"id":"M03-P1-S3-Q22","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["A","B","両方","選ばない"],"answer":2,"b":-0.3,"explanation":"今回は納期優先でB。","audioText":"女：A商品の不良率は1％ですが納期が長いです。B商品は不良率2％で即納できます。男：今回は急ぎなのでBにしよう。 選ぶ商品はどれですか。 1、A。 2、B。 3、両方。 4、選ばない。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"調達"}},{"id":"M03-P1-S3-Q23","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["1名","2名","3名","6名"],"answer":1,"b":-0.7,"explanation":"6-(3+2)=1。","audioText":"男：来月の展示会スタッフは6名必要です。女：営業から3名、企画から2名出せます。男：あと1名、総務にお願いしましょう。 総務に何名依頼しますか。 1、1名。 2、2名。 3、3名。 4、6名。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"人員配置"}},{"id":"M03-P1-S3-Q24","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["今日午前","今日午後","明日","来週"],"answer":3,"b":-0.5,"explanation":"法務確認後、明日署名。","audioText":"女：契約書は先方確認済みです。男：法務の最終確認は？女：今日午後に終わる予定です。男：では明日署名しましょう。 署名はいつですか。 1、今日午前。 2、今日午後。 3、明日。 4、来週。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"契約"}},{"id":"M03-P1-S3-Q25","part":1,"section":3,"type":"listening_dialogue","prompt":"","options":["データ削除だけ","今月中に容量追加","来月まで待つ","サーバ停止"],"answer":2,"b":0.0,"explanation":"将来不足を見込み今月追加。","audioText":"男：サーバ容量は80％まで来ています。女：来月のデータ増加で95％になる見込みです。男：今月中に容量を追加しておこう。 何をすることにしましたか。 1、データ削除だけ。 2、今月中に容量追加。 3、来月まで待つ。 4、サーバ停止。","visual":{"kind":"emoji","scene":"👨‍💼 💬 👩‍💼","sub":"IT運用"}},{"id":"M03-P2-S1-Q26","part":2,"section":1,"type":"listen_read_situation","prompt":"どの区分ですか。","options":["A","B","C","D"],"answer":2,"b":-0.6,"explanation":"30～39歳はB。","audioText":"担当：会員区分は年齢で決まります。35歳の社員が入会します。","visual":{"kind":"table","title":"会員区分","headers":["区分","年齢"],"rows":[["A","～29"],["B","30～39"],["C","40～49"],["D","50～"]]}},{"id":"M03-P2-S1-Q27","part":2,"section":1,"type":"listen_read_situation","prompt":"どの便ですか。","options":["A","B","C","D"],"answer":2,"b":0.0,"explanation":"直行便のうち最速到着はB。","audioText":"担当：午後の便で最も早く到着する直行便を選びます。","visual":{"kind":"table","title":"便","headers":["便","出発","到着","乗換"],"rows":[["A","13:00","15:30","1"],["B","13:20","15:10","0"],["C","14:00","15:20","0"],["D","12:50","15:00","1"]]}},{"id":"M03-P2-S1-Q28","part":2,"section":1,"type":"listen_read_situation","prompt":"最小で使える部屋はどれですか。","options":["A","B","C","D"],"answer":3,"b":-0.5,"explanation":"定員16のCが最小で条件を満たす。","audioText":"総務：会議室は参加人数以上の定員が必要です。参加者は14人です。","visual":{"kind":"table","title":"会議室","headers":["部屋","定員"],"rows":[["A","8"],["B","12"],["C","16"],["D","30"]]}},{"id":"M03-P2-S1-Q29","part":2,"section":1,"type":"listen_read_situation","prompt":"残り営業日は何日ですか。","options":["1日","2日","3日","4日"],"answer":2,"b":0.2,"explanation":"29日、30日の2営業日。","audioText":"担当：締切日は9月30日です。営業日だけ数えます。今日は9月28日月曜です。","visual":{"kind":"note","title":"申請期限","lines":["今日：9/28（月）","締切：9/30（水）","土日除外"]}},{"id":"M03-P2-S1-Q30","part":2,"section":1,"type":"listen_read_situation","prompt":"条件を満たす店はどれですか。","options":["A","B","C","D"],"answer":4,"b":-0.1,"explanation":"Dのみ4,800円・徒歩4分。","audioText":"担当：予算は一人5,000円以内、駅から徒歩5分以内です。","visual":{"kind":"table","title":"会食候補","headers":["店","一人","駅徒歩"],"rows":[["A","4,500","8分"],["B","5,500","3分"],["C","5,000","6分"],["D","4,800","4分"]]}},{"id":"M03-P2-S2-Q31","part":2,"section":2,"type":"listen_read_data","prompt":"最も成長した部署はどれですか。","options":["A","B","C","D"],"answer":3,"b":-0.4,"explanation":"Cが+18%。","audioText":"担当：前年より売上成長率が高い部署を重点支援します。","visual":{"kind":"table","title":"成長率","headers":["部署","成長率"],"rows":[["A","8%"],["B","12%"],["C","18%"],["D","5%"]]}},{"id":"M03-P2-S2-Q32","part":2,"section":2,"type":"listen_read_data","prompt":"どの案ですか。","options":["A","B","C","D"],"answer":2,"b":-0.7,"explanation":"Bの35分が最短。","audioText":"上司：処理時間が最も短い案を選びます。","visual":{"kind":"table","title":"処理時間","headers":["案","時間"],"rows":[["A","50分"],["B","35分"],["C","60分"],["D","45分"]]}},{"id":"M03-P2-S2-Q33","part":2,"section":2,"type":"listen_read_data","prompt":"対象地域はいくつですか。","options":["1","2","3","4"],"answer":2,"b":-0.3,"explanation":"東12,000と南10,500の2地域。","audioText":"担当：顧客単価が1万円以上の地域を優先します。","visual":{"kind":"table","title":"顧客単価","headers":["地域","単価"],"rows":[["東","12,000"],["西","9,000"],["南","10,500"],["北","8,500"]]}},{"id":"M03-P2-S2-Q34","part":2,"section":2,"type":"listen_read_data","prompt":"損益分岐点数量はどれですか。","options":["200","250","300","450"],"answer":3,"b":0.8,"explanation":"限界利益3000円、900000/3000=300。","audioText":"経理：売価8,000円、変動費5,000円、固定費90万円です。","visual":{"kind":"note","title":"損益","lines":["売価：8,000円","変動費：5,000円","固定費：900,000円"]}},{"id":"M03-P2-S2-Q35","part":2,"section":2,"type":"listen_read_data","prompt":"どの経路が使えますか。","options":["A","B","C","D"],"answer":1,"b":0.1,"explanation":"Aは15:50、9800円。","audioText":"担当：午後4時までに到着し、費用は1万円以下が条件です。","visual":{"kind":"table","title":"経路","headers":["経路","到着","費用"],"rows":[["A","15:50","9,800"],["B","15:40","12,000"],["C","16:10","8,000"],["D","16:00","10,500"]]}},{"id":"M03-P2-S2-Q36","part":2,"section":2,"type":"listen_read_data","prompt":"対象はどれですか。","options":["営業だけ","開発だけ","営業と開発","総務と経理"],"answer":3,"b":-0.2,"explanation":"営業75、開発68。","audioText":"人事：研修受講率80％未満の部署に追加研修を行います。","visual":{"kind":"table","title":"受講率","headers":["部署","率"],"rows":[["営業","75%"],["総務","92%"],["開発","68%"],["経理","85%"]]}},{"id":"M03-P2-S2-Q37","part":2,"section":2,"type":"listen_read_data","prompt":"どのプランですか。","options":["A","B","C","D"],"answer":2,"b":0.0,"explanation":"B=500GB・8万。","audioText":"担当：容量500GB以上、月額8万円以下のプランを選びます。","visual":{"kind":"table","title":"クラウド","headers":["プラン","容量","月額"],"rows":[["A","300GB","5万"],["B","500GB","8万"],["C","1TB","12万"],["D","450GB","7万"]]}},{"id":"M03-P2-S2-Q38","part":2,"section":2,"type":"listen_read_data","prompt":"どの店舗ですか。","options":["A","B","C","D"],"answer":4,"b":0.1,"explanation":"Dは80→96で+16pt。","audioText":"上司：改善率が最も高い店舗を表彰します。","visual":{"kind":"table","title":"顧客評価","headers":["店","前","後"],"rows":[["A","70","78"],["B","82","88"],["C","65","75"],["D","80","96"]]}},{"id":"M03-P2-S2-Q39","part":2,"section":2,"type":"listen_read_data","prompt":"どの支店ですか。","options":["A","B","C","D"],"answer":1,"b":0.7,"explanation":"A=1200/20=60で最大。","audioText":"担当：1人あたり売上が最も高い支店を確認します。","visual":{"kind":"table","title":"支店","headers":["支店","売上","人数"],"rows":[["A","1200","20"],["B","1500","30"],["C","900","18"],["D","1600","40"]]}},{"id":"M03-P2-S2-Q40","part":2,"section":2,"type":"listen_read_data","prompt":"対象はどれですか。","options":["A","B","C","D"],"answer":1,"b":-0.5,"explanation":"Aは9/30で期限切れ。","audioText":"総務：有効期限が今日より前の証明書だけ更新対象です。今日は10月1日です。","visual":{"kind":"table","title":"証明書","headers":["社員","期限"],"rows":[["A","9/30"],["B","10/1"],["C","10/5"],["D","11/1"]]}},{"id":"M03-P2-S3-Q41","part":2,"section":3,"type":"listen_read_dialogue","prompt":"最も評価される商品はどれですか。","options":["A","B","C","D"],"answer":4,"b":-0.4,"explanation":"利益率最高D。","audioText":"部長：今回は売上ではなく利益率を重視します。","visual":{"kind":"table","title":"商品","headers":["商品","売上","利益率"],"rows":[["A","200","12%"],["B","180","18%"],["C","160","20%"],["D","130","28%"]]}},{"id":"M03-P2-S3-Q42","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どの案ですか。","options":["A","B","C","D"],"answer":3,"b":0.1,"explanation":"予算内でCの見込み300が最大。","audioText":"担当：予算50万円以内で、参加見込みが最も多いイベント案を選びます。","visual":{"kind":"table","title":"イベント","headers":["案","費用","参加見込"],"rows":[["A","30万","180"],["B","55万","400"],["C","48万","300"],["D","25万","150"]]}},{"id":"M03-P2-S3-Q43","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どこですか。","options":["電話","メール","チャット","店舗"],"answer":2,"b":0.2,"explanation":"メール50→100で+100%。","audioText":"上司：問い合わせ増加率が最も大きい窓口に人を増やします。","visual":{"kind":"table","title":"問い合わせ","headers":["窓口","先月","今月"],"rows":[["電話","80","100"],["メール","50","100"],["チャット","100","140"],["店舗","40","45"]]}},{"id":"M03-P2-S3-Q44","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どこですか。","options":["A","B","C","D"],"answer":3,"b":-0.1,"explanation":"条件内A/B/CのうちCが最安。","audioText":"担当：駅徒歩5分以内を必須条件にし、その中で賃料が最も安い場所を選びます。","visual":{"kind":"table","title":"候補地","headers":["候補","徒歩","賃料"],"rows":[["A","3分","50万"],["B","5分","42万"],["C","4分","39万"],["D","8分","30万"]]}},{"id":"M03-P2-S3-Q45","part":2,"section":3,"type":"listen_read_dialogue","prompt":"5年総額が安いのはどちらですか。","options":["A","B","同額","不明"],"answer":2,"b":0.9,"explanation":"A=20+3×60=200万円、B=50+2×60=170万円なのでB社。","audioText":"男：A社は導入20万円、月額3万円。B社は導入50万円、月額2万円。女：5年間ならどうですか。","visual":{"kind":"table","title":"費用(万円)","headers":["会社","導入","月額"],"rows":[["A","20","3"],["B","50","2"]]}},{"id":"M03-P2-S3-Q46","part":2,"section":3,"type":"listen_read_dialogue","prompt":"認定される会社はいくつですか。","options":["1","2","3","4"],"answer":1,"b":0.2,"explanation":"Aのみ両条件。","audioText":"担当：納期遵守95％以上、不良率1.5％以下の会社を優良認定します。","visual":{"kind":"table","title":"仕入先","headers":["社","納期","不良率"],"rows":[["A","97%","1.0%"],["B","96%","2.0%"],["C","93%","1.0%"],["D","95%","1.8%"]]}},{"id":"M03-P2-S3-Q47","part":2,"section":3,"type":"listen_read_dialogue","prompt":"顧客先には何時ごろ着きますか。","options":["10:30","10:40","10:45","11:00"],"answer":3,"b":-0.4,"explanation":"10:30+15分=10:45。","audioText":"秘書：ホテルを9時に出発し、駅まで20分。9時40分の電車に乗り、10時30分到着。駅から顧客まで15分です。","visual":{"kind":"route","title":"移動","lines":["ホテル 9:00発","駅まで20分","電車 9:40→10:30","駅→顧客 15分"]}},{"id":"M03-P2-S3-Q48","part":2,"section":3,"type":"listen_read_dialogue","prompt":"どう対応しますか。","options":["4人で運営","田中を夕方へ移す","営業時間短縮","採用する"],"answer":2,"b":-0.5,"explanation":"余剰人員を夕方へ移す。","audioText":"店長：夕方は5人必要ですが4人です。午前は1人余っています。田中さんは時間変更可能です。","visual":{"kind":"table","title":"人員","headers":["時間","必要","現在"],"rows":[["午前","3","4"],["夕方","5","4"]]}},{"id":"M03-P2-S3-Q49","part":2,"section":3,"type":"listen_read_dialogue","prompt":"条件を満たす製品はどれですか。","options":["A","B","C","D"],"answer":4,"b":0.0,"explanation":"Dのみ防水○・2年保証。","audioText":"担当：必須条件は防水と2年保証です。","visual":{"kind":"table","title":"製品比較","headers":["製品","防水","保証"],"rows":[["A","○","1年"],["B","×","3年"],["C","×","1年"],["D","○","2年"]]}},{"id":"M03-P2-S3-Q50","part":2,"section":3,"type":"listen_read_dialogue","prompt":"最優先はどれですか。","options":["軽微な遅刻","紙不足","基幹システム停止","会議室不足"],"answer":3,"b":0.6,"explanation":"事業停止リスク。","audioText":"責任者：頻度は低くても事業停止につながるリスクを最優先します。","visual":{"kind":"table","title":"リスク","headers":["項目","頻度","影響"],"rows":[["遅刻","高","小"],["紙不足","中","小"],["基幹停止","低","極大"],["会議室不足","中","中"]]}},{"id":"M03-P3-S1-Q51","part":3,"section":1,"type":"reading_vocab","prompt":"担当者の説明を聞いた＿＿、正式に申し込むことにした。","options":["うえで","うちに","うえに","以上"],"answer":1,"b":0.5,"explanation":"～たうえで＝その後に判断。"},{"id":"M03-P3-S1-Q52","part":3,"section":1,"type":"reading_vocab","prompt":"新制度は来月1日＿＿実施されます。","options":["をもって","にかけて","に応じて","を限り"],"answer":1,"b":0.8,"explanation":"日付を区切りとして実施開始。"},{"id":"M03-P3-S1-Q53","part":3,"section":1,"type":"reading_vocab","prompt":"急な依頼だったので断ろうと思ったが、重要顧客なので引き受け＿＿。","options":["るはずがない","ざるを得なかった","ないことはない","に違いない"],"answer":2,"b":0.7,"explanation":"やむを得ず引き受けた。"},{"id":"M03-P3-S1-Q54","part":3,"section":1,"type":"reading_vocab","prompt":"問い合わせが増えている＿＿、担当者を増員した。","options":["ことから","からには","わりには","こそ"],"answer":1,"b":0.3,"explanation":"原因・根拠。"},{"id":"M03-P3-S1-Q55","part":3,"section":1,"type":"reading_vocab","prompt":"本件は社内調整が必要なため、回答まで少々お時間を＿＿。","options":["頂戴します","拝見します","伺います","召し上がります"],"answer":1,"b":0.2,"explanation":"時間をもらう丁寧表現。"},{"id":"M03-P3-S1-Q56","part":3,"section":1,"type":"reading_vocab","prompt":"今回の提案は費用面＿＿、運用面でもメリットが大きい。","options":["のみならず","に限り","に際して","に応じて"],"answer":1,"b":0.6,"explanation":"AのみならずBも。"},{"id":"M03-P3-S1-Q57","part":3,"section":1,"type":"reading_vocab","prompt":"新製品の発売に＿＿、販売員向け研修を実施する。","options":["先立ち","伴いだけ","沿い","応じ"],"answer":1,"b":0.6,"explanation":"～に先立ち＝前もって。"},{"id":"M03-P3-S1-Q58","part":3,"section":1,"type":"reading_vocab","prompt":"担当者が不在のため、私が代わってご用件を＿＿。","options":["承ります","おっしゃいます","頂戴されます","参ります"],"answer":1,"b":0.5,"explanation":"用件を聞く謙譲語「承る」。"},{"id":"M03-P3-S1-Q59","part":3,"section":1,"type":"reading_vocab","prompt":"その件につきましては、担当部署に確認の＿＿ご連絡します。","options":["うえ","際","限り","ところ"],"answer":1,"b":0.2,"explanation":"確認のうえ＝確認してから。"},{"id":"M03-P3-S1-Q60","part":3,"section":1,"type":"reading_vocab","prompt":"条件が変更になる＿＿がありますので、最新情報をご確認ください。","options":["可能性","絶対","目当て","手間"],"answer":1,"b":-0.3,"explanation":"不確実性＝可能性。"},{"id":"M03-P3-S2-Q61","part":3,"section":2,"type":"reading_expression","prompt":"取引先へ納期遅延を知らせる冒頭として最も適切なのはどれですか。","options":["遅れます。","このたびは納期に遅れが生じる見込みとなり、誠に申し訳ございません。","予定が変わりました。","待ってください。"],"answer":2,"b":0.0,"explanation":"正式な謝罪と状況説明。"},{"id":"M03-P3-S2-Q62","part":3,"section":2,"type":"reading_expression","prompt":"会議で相手の意見に賛成しつつ補足するとき最も適切なのはどれですか。","options":["その通りです。終わり。","おっしゃる通りです。そのうえで、運用面について一点補足させてください。","でも違います。","私の方が正しいです。"],"answer":2,"b":0.4,"explanation":"同意＋補足の流れ。"},{"id":"M03-P3-S2-Q63","part":3,"section":2,"type":"reading_expression","prompt":"顧客に選択肢を提示するとき最も適切なのはどれですか。","options":["AかBにしてください。","A案とB案をご用意しておりますが、どちらがご都合よろしいでしょうか。","好きな方で。","Aの方がいいです。"],"answer":2,"b":-0.2,"explanation":"選択肢を丁寧に提示。"},{"id":"M03-P3-S2-Q64","part":3,"section":2,"type":"reading_expression","prompt":"上司への報告で、原因がまだ不明な場合最も適切なのはどれですか。","options":["原因は絶対にサーバです。","現時点では原因は特定できておらず、現在調査中です。","原因は分かりません。","たぶんサーバです。"],"answer":2,"b":-0.2,"explanation":"不確定情報を明示。"},{"id":"M03-P3-S2-Q65","part":3,"section":2,"type":"reading_expression","prompt":"電話で相手の声が聞こえにくいとき最も適切なのはどれですか。","options":["聞こえない。","恐れ入ります、お電話が少々遠いようですが、もう一度お願いできますでしょうか。","大きな声で。","何ですか。"],"answer":2,"b":0.1,"explanation":"電話特有の丁寧表現。"},{"id":"M03-P3-S2-Q66","part":3,"section":2,"type":"reading_expression","prompt":"訪問先で予定より早く到着したとき最も適切なのはどれですか。","options":["早く来ました。","予定より早く到着してしまい、失礼いたしました。お時間までこちらでお待ちしてもよろしいでしょうか。","今会えますか。","待ちます。"],"answer":2,"b":0.3,"explanation":"早着への配慮。"},{"id":"M03-P3-S2-Q67","part":3,"section":2,"type":"reading_expression","prompt":"社内メールで期限を明確に伝える文として最も適切なのはどれですか。","options":["早めに出してください。","恐れ入りますが、9月30日17時までにご提出をお願いいたします。","今週中かな。","できたらください。"],"answer":2,"b":-0.5,"explanation":"期限が明確。"},{"id":"M03-P3-S2-Q68","part":3,"section":2,"type":"reading_expression","prompt":"顧客から感謝されたときの返答として自然なのはどれですか。","options":["当然です。","とんでもございません。お役に立てて何よりです。","どういたしましてね。","感謝してください。"],"answer":2,"b":-0.1,"explanation":"謙虚で自然な返答。"},{"id":"M03-P3-S2-Q69","part":3,"section":2,"type":"reading_expression","prompt":"条件付きで依頼を受けるとき最も適切なのはどれですか。","options":["できます。","納期を一週間延長していただければ、対応可能です。","条件があります。","やってもいいです。"],"answer":2,"b":0.1,"explanation":"条件と可否を明確にする。"},{"id":"M03-P3-S2-Q70","part":3,"section":2,"type":"reading_expression","prompt":"会議終了時の司会者の発言として最も適切なのはどれですか。","options":["終わります。","以上をもちまして、本日の会議を終了いたします。ご参加ありがとうございました。","もう帰っていいです。","会議は終わりです。"],"answer":2,"b":-0.3,"explanation":"正式な閉会表現。"},{"id":"M03-P3-S3-Q71","part":3,"section":3,"type":"reading_comprehension","prompt":"交通費はいつまでに申請しますか。","options":["月末","利用日から10日以内","翌日","30日以内"],"answer":2,"b":-0.6,"explanation":"10日以内。","passage":"【経費精算の変更】\n10月から交通費精算は月末一括ではなく、利用日から10日以内に申請する。電子領収書はPDF添付でよい。紙の領収書を受け取った場合は、システムへ画像を登録したうえで原本を月末まで保管する。1件3万円以上の支出は、精算前に部長の承認が必要である。"},{"id":"M03-P3-S3-Q72","part":3,"section":3,"type":"reading_comprehension","prompt":"3万円以上の支出で必要なのは何ですか。","options":["課長承認","部長の事前承認","原本廃棄","申請不要"],"answer":2,"b":-0.3,"explanation":"精算前の部長承認。","passage":"【経費精算の変更】\n10月から交通費精算は月末一括ではなく、利用日から10日以内に申請する。電子領収書はPDF添付でよい。紙の領収書を受け取った場合は、システムへ画像を登録したうえで原本を月末まで保管する。1件3万円以上の支出は、精算前に部長の承認が必要である。"},{"id":"M03-P3-S3-Q73","part":3,"section":3,"type":"reading_comprehension","prompt":"満足度が最も高いのはどれですか。","options":["電話","チャット","メール","同じ"],"answer":2,"b":-0.7,"explanation":"チャット88%。","passage":"【顧客サポート改善】\n問い合わせの平均回答時間は、電話が3分、チャットが8分、メールが6時間だった。満足度は電話82％、チャット88％、メール70％。チームは、満足度が最も低いメール対応について、テンプレート整備と担当者増員を行い、平均回答時間を3時間以内にする目標を設定した。"},{"id":"M03-P3-S3-Q74","part":3,"section":3,"type":"reading_comprehension","prompt":"改善対象はどれですか。","options":["電話","チャット","メール","全て"],"answer":3,"b":-0.6,"explanation":"満足度最低のメール。","passage":"【顧客サポート改善】\n問い合わせの平均回答時間は、電話が3分、チャットが8分、メールが6時間だった。満足度は電話82％、チャット88％、メール70％。チームは、満足度が最も低いメール対応について、テンプレート整備と担当者増員を行い、平均回答時間を3時間以内にする目標を設定した。"},{"id":"M03-P3-S3-Q75","part":3,"section":3,"type":"reading_comprehension","prompt":"本社ビルに入館できない時間帯はどれですか。","options":["22時～翌2時","23時～1時","22時～23時","1時～2時"],"answer":1,"b":-0.4,"explanation":"点検全時間帯。","passage":"【設備点検のお知らせ】\n10月8日22時から翌2時まで電気設備の点検を行う。この間、本社ビルへの入館はできない。サーバは非常用電源で稼働を継続するが、一部社内システムは23時から1時まで停止する予定である。作業が早く終了した場合でも、システム再開時刻は変更しない。"},{"id":"M03-P3-S3-Q76","part":3,"section":3,"type":"reading_comprehension","prompt":"一部システムの再開は何時ですか。","options":["作業終了直後","0時","1時","2時"],"answer":3,"b":-0.1,"explanation":"1時に再開予定。","passage":"【設備点検のお知らせ】\n10月8日22時から翌2時まで電気設備の点検を行う。この間、本社ビルへの入館はできない。サーバは非常用電源で稼働を継続するが、一部社内システムは23時から1時まで停止する予定である。作業が早く終了した場合でも、システム再開時刻は変更しない。"},{"id":"M03-P3-S3-Q77","part":3,"section":3,"type":"reading_comprehension","prompt":"候補者Aの特徴はどれですか。","options":["経験が短い","海外勤務希望","業界経験が長い","中国語が使える"],"answer":3,"b":-0.6,"explanation":"Aは経験長い。","passage":"【採用面接メモ】\n候補者Aは業界経験が長く即戦力が期待できるが、海外勤務は希望していない。候補者Bは経験は短いものの英語と中国語が使え、海外勤務にも前向きである。今回の募集ポジションは半年後に海外拠点へ赴任する可能性が高いため、人事部はBを最終面接へ進めることにした。"},{"id":"M03-P3-S3-Q78","part":3,"section":3,"type":"reading_comprehension","prompt":"Bが最終面接へ進む主な理由は何ですか。","options":["給与が低い","海外勤務への適性","経験が最長","国内勤務希望"],"answer":2,"b":-0.2,"explanation":"募集要件との適合。","passage":"【採用面接メモ】\n候補者Aは業界経験が長く即戦力が期待できるが、海外勤務は希望していない。候補者Bは経験は短いものの英語と中国語が使え、海外勤務にも前向きである。今回の募集ポジションは半年後に海外拠点へ赴任する可能性が高いため、人事部はBを最終面接へ進めることにした。"},{"id":"M03-P3-S3-Q79","part":3,"section":3,"type":"reading_comprehension","prompt":"キャンペーン中のA商品の安全在庫基準はいくつですか。","options":["30","40","45","60"],"answer":3,"b":0.1,"explanation":"30×1.5=45。","passage":"【在庫管理方針】\n今後、A商品は安全在庫を30個、B商品は50個とする。在庫数が安全在庫を下回った時点で、Aは100個、Bは150個を発注する。ただし、キャンペーン期間中は需要増を考慮し、安全在庫基準を通常の1.5倍として判断する。現在キャンペーン中で、Aの在庫は40個、Bは80個である。"},{"id":"M03-P3-S3-Q80","part":3,"section":3,"type":"reading_comprehension","prompt":"現在、発注判断が必要なのはどの商品ですか。","options":["Aのみ","Bのみ","両方","どちらも不要"],"answer":1,"b":0.5,"explanation":"Aは40<45、Bは80>=75。","passage":"【在庫管理方針】\n今後、A商品は安全在庫を30個、B商品は50個とする。在庫数が安全在庫を下回った時点で、Aは100個、Bは150個を発注する。ただし、キャンペーン期間中は需要増を考慮し、安全在庫基準を通常の1.5倍として判断する。現在キャンペーン中で、Aの在庫は40個、Bは80個である。"}]}};

  let selectedExamId='BJT-MOCK-01';
  let tickTimer=null,transitionTimer=null,speakingId=null;
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const fmtSec=n=>{n=Math.max(0,Math.floor(n));const m=Math.floor(n/60),s=n%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`};
  function defaultStore(){return {active:null,history:[]}}
  function load(){try{return {...defaultStore(),...JSON.parse(localStorage.getItem(STORAGE)||'{}')}}catch(e){return defaultStore()}}
  function save(s){localStorage.setItem(STORAGE,JSON.stringify(s))}
  function get(){return load()}
  function setActive(a){const s=get();s.active=a;save(s)}
  function updateActive(fn){const s=get();if(!s.active)return null;fn(s.active);save(s);return s.active}
  function examDef(id){return EXAMS[id]||EXAMS['BJT-MOCK-01']}
  function questionsFor(id){return examDef(id).questions}
  function activeQuestions(a){return questionsFor(a?.examId||selectedExamId)}
  function partLabel(p){return p===1?'第1部｜聴解':p===2?'第2部｜聴読解':'第3部｜読解'}
  function sectionLabel(q){if(q.part===1)return q.section===1?'場面把握':q.section===2?'発言聴解':'総合聴解';if(q.part===2)return q.section===1?'状況把握':q.section===2?'資料聴読解':'総合聴読解';return q.section===1?'語彙・文法':q.section===2?'表現読解':'総合読解'}
  function level(score){if(score>=600)return 'J1+';if(score>=530)return 'J1';if(score>=420)return 'J2';if(score>=320)return 'J3';if(score>=200)return 'J4';return 'J5'}
  function itemDiscrimination(q){const map={'1-1':.8,'1-2':1.0,'1-3':1.15,'2-1':.9,'2-2':1.1,'2-3':1.2,'3-1':1.15,'3-2':1.05,'3-3':1.2};return map[`${q.part}-${q.section}`]||1}
  function estimateScore(active){const QUESTIONS=activeQuestions(active),answered=QUESTIONS.map(q=>({q,y:active.answers[q.id]==null?0:(active.answers[q.id]===q.answer?1:0)})),correct=answered.reduce((a,x)=>a+x.y,0);if(correct===0)return{score:0,theta:-4,se:0,low:0,high:40};if(correct===QUESTIONS.length)return{score:800,theta:4,se:0,low:760,high:800};let th=0,info=0;for(let it=0;it<50;it++){let g=0;info=0;for(const {q,y} of answered){const a=itemDiscrimination(q),p=1/(1+Math.exp(-a*(th-q.b)));g+=a*(y-p);info+=a*a*p*(1-p)}if(info<1e-6)break;const step=clamp(g/info,-.8,.8);th=clamp(th+step,-3.5,3.5);if(Math.abs(step)<1e-6)break}info=answered.reduce((acc,{q})=>{const a=itemDiscrimination(q),p=1/(1+Math.exp(-a*(th-q.b)));return acc+a*a*p*(1-p)},0);const score=Math.round(clamp(400+110*th,0,800)),se=info>0?110/Math.sqrt(info):45;return{score,theta:th,se,low:Math.round(clamp(score-se,0,800)),high:Math.round(clamp(score+se,0,800))}}
  function scoreBreakdown(active){const QUESTIONS=activeQuestions(active),out={};for(const p of [1,2,3]){const list=QUESTIONS.filter(q=>q.part===p),correct=list.filter(q=>active.answers[q.id]===q.answer).length;out[p]={correct,total:list.length,accuracy:Math.round(correct/list.length*100)}}return out}
  function renderVisual(v){if(!v)return'';if(v.kind==='emoji')return `<div class="mock-visual mock-scene-visual"><div class="mock-scene-glyph">${esc(v.scene)}</div>${v.sub?`<div class="mock-scene-sub">${esc(v.sub)}</div>`:''}</div>`;if(v.kind==='table')return `<div class="mock-visual"><h3>${esc(v.title||'資料')}</h3><div class="mock-table-wrap"><table class="mock-data-table"><thead><tr>${(v.headers||[]).map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${(v.rows||[]).map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;if(['note','notice','invoice','agenda','route'].includes(v.kind))return `<div class="mock-visual mock-paper"><div class="mock-paper-title">${esc(v.title||'資料')}</div>${(v.lines||[]).map(x=>`<div class="mock-paper-line">${esc(x)}</div>`).join('')}</div>`;return''}
  function audioRequired(q){return q.part<=2} function hasTextOptions(q){return q.part>=2}
  function questionNumberInPart(q,a){const list=activeQuestions(a).filter(x=>x.part===q.part);return list.findIndex(x=>x.id===q.id)+1}
  function getCurrent(a){return activeQuestions(a)[a.index]||null}
  function cleanupTimers(){if(tickTimer){clearInterval(tickTimer);tickTimer=null}if(transitionTimer){clearTimeout(transitionTimer);transitionTimer=null}}
  function beginPart(part){const a=get().active;if(!a)return;const QUESTIONS=activeQuestions(a);a.phase='question';a.part=part;a.partStartedAt=Date.now();a.partDeadline=Date.now()+PART_LIMITS[part]*1000;const idx=QUESTIONS.findIndex(q=>q.part===part);a.index=idx<0?a.index:idx;setActive(a);renderIntoCurrent()}
  function startExam(examId){if(!('speechSynthesis' in window)){alert('このブラウザでは音声合成が利用できないため、聴解・聴読解を本番形式で実施できません。');return}selectedExamId=examId||selectedExamId;const now=Date.now();setActive({examId:selectedExamId,status:'active',phase:'question',strictNoBack:true,startedAt:now,part:1,index:0,partStartedAt:now,partDeadline:now+PART_LIMITS[1]*1000,answers:{},played:{},audioErrors:{}});renderIntoCurrent()}
  function abandon(){if('speechSynthesis'in window)speechSynthesis.cancel();speakingId=null;cleanupTimers();const s=get();s.active=null;save(s);document.body.classList.remove('mock-exam-running');renderIntoCurrent()}
  function transitionTo(nextPart){const a=get().active;if(!a)return;a.phase='transition';a.nextPart=nextPart;a.transitionUntil=Date.now()+8000;setActive(a);renderIntoCurrent()}
  function finishExam(reason='completed'){if('speechSynthesis'in window)speechSynthesis.cancel();speakingId=null;cleanupTimers();const s=get(),a=s.active;if(!a)return;a.status='finished';a.phase='finished';a.finishedAt=Date.now();a.finishReason=reason;const est=estimateScore(a),bd=scoreBreakdown(a);a.result={...est,breakdown:bd,correct:Object.values(bd).reduce((x,y)=>x+y.correct,0),total:80,level:level(est.score)};s.history=[{examId:a.examId,startedAt:a.startedAt,finishedAt:a.finishedAt,score:a.result.score,level:a.result.level,correct:a.result.correct,breakdown:a.result.breakdown,target400:a.result.score>=400},...(s.history||[])].slice(0,30);s.active=a;save(s);renderIntoCurrent()}
  function expirePart(){const a=get().active;if(!a||a.status!=='active'||a.phase!=='question')return;if(a.part<3)transitionTo(a.part+1);else finishExam('time')}
  function nextQuestion(){const s=get(),a=s.active;if(!a)return;const QUESTIONS=activeQuestions(a),q=getCurrent(a);if(!q)return;if(audioRequired(q)&&!a.played[q.id])return;if(speakingId===q.id)return;if(a.answers[q.id]==null&&!confirm('未作答のまま次へ進むと、この問題には戻れません。次へ進みますか？'))return;const next=QUESTIONS[a.index+1];if(!next){finishExam('completed');return}if(next.part!==q.part){transitionTo(next.part);return}a.index++;setActive(a);renderIntoCurrent()}
  function selectAnswer(qid,n){updateActive(a=>{if(a.status==='active'&&a.phase==='question')a.answers[qid]=n});const root=document.getElementById('view-mockexam');if(root)renderQuestion(root,get().active)}
  function chooseVoice(){const voices=speechSynthesis.getVoices?speechSynthesis.getVoices():[];return voices.find(v=>/^ja(-|_)/i.test(v.lang)&&/Google|Microsoft|Kyoko|Otoya|Haruka|Nanami/i.test(v.name))||voices.find(v=>/^ja(-|_)/i.test(v.lang))||null}
  function playAudio(q){const s=get(),a=s.active;if(!a||a.played[q.id]||speakingId)return;a.played[q.id]=Date.now();setActive(a);const u=new SpeechSynthesisUtterance(q.audioText||'');u.lang='ja-JP';u.rate=.9;u.pitch=1;const v=chooseVoice();if(v)u.voice=v;speakingId=q.id;u.onend=()=>{speakingId=null;renderIntoCurrent()};u.onerror=()=>{speakingId=null;updateActive(x=>x.audioErrors[q.id]=true);renderIntoCurrent()};try{speechSynthesis.speak(u)}catch(e){speakingId=null;updateActive(x=>x.audioErrors[q.id]=true);renderIntoCurrent()}renderIntoCurrent()}
  function audioTest(){if(!('speechSynthesis'in window)){alert('音声合成に対応していません。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance('音声テストです。ヘッドフォンの音量を確認してください。');u.lang='ja-JP';u.rate=.9;const v=chooseVoice();if(v)u.voice=v;speechSynthesis.speak(u)}
  function tick(root){const a=get().active;if(!a||a.status!=='active')return;if(a.phase==='transition'){const remain=Math.ceil((a.transitionUntil-Date.now())/1000),el=root.querySelector('#mockTransitionCount');if(el)el.textContent=Math.max(0,remain);if(remain<=0)beginPart(a.nextPart);return}if(a.phase!=='question')return;const remain=Math.ceil((a.partDeadline-Date.now())/1000),el=root.querySelector('#mockTimer');if(el)el.textContent=fmtSec(remain);if(remain<=0)expirePart()}
  function renderHome(root){document.body.classList.remove('mock-exam-running');cleanupTimers();const store=get(),hist=store.history||[];root.innerHTML=`<section class="card mock-hero"><div><span class="player-kicker">BJT MOCK EXAM</span><h2>BJT 模擬試驗｜3回・各80題</h2><p>三回皆為本 App 原創模擬題。各回均為聴解25＋聴読解25＋読解30，並採不可回頭、音聲一次的嚴格模式。</p></div><div class="mock-score-target"><strong>400</strong><span>你的目標線</span></div></section><section class="grid mock-exam-pick-grid">${Object.values(EXAMS).map(ex=>{const last=hist.find(h=>h.examId===ex.id);return `<article class="card mock-exam-pick"><span class="player-kicker">${esc(ex.code)}</span><h3>${esc(ex.title)}</h3><p>80題｜105分鐘｜0–800 模擬尺度分數</p>${last?`<div class="mock-last-score"><b>${last.score}</b><span>${esc(last.level)}・${last.correct}/80</span></div>`:''}<button class="btn primary" data-start-exam="${esc(ex.id)}">開始${esc(ex.title)}</button></article>`}).join('')}</section><section class="grid mock-part-grid"><article class="card"><span class="player-kicker">PART 1</span><h3>聴解｜25題</h3><p>場面把握 5＋発言聴解 10＋総合聴解 10</p><b>45:00</b></article><article class="card"><span class="player-kicker">PART 2</span><h3>聴読解｜25題</h3><p>状況把握 5＋資料聴読解 10＋総合聴読解 10</p><b>30:00</b></article><article class="card"><span class="player-kicker">PART 3</span><h3>読解｜30題</h3><p>語彙・文法 10＋表現読解 10＋総合読解 10</p><b>30:00</b></article></section><section class="card mock-rules"><h3>試驗規則</h3><ul><li>第1・2部的音聲每題只能播放一次；播放後不可重播。</li><li>依你的設定，全三部均不可返回前題。</li><li>各部時間到自動進入下一部；沒有休息時間。</li><li>考試中不顯示正解或詳解；全卷完成後才開放。</li><li>0–800 為 IRT-style 模擬尺度分數，不等同官方 BJT 成績。</li></ul><button class="btn" id="mockAudioTest">🔊 音量測試</button></section>${hist.length?`<section class="card"><h3>最近成績</h3><div class="mock-history">${hist.map(h=>`<div><b>${h.score}</b><span>${esc(examDef(h.examId).title)}｜${esc(h.level)}｜${h.correct}/80｜${new Date(h.finishedAt).toLocaleString()}</span><em class="${h.target400?'good':'bad'}">${h.target400?'400線達成':'400線未達'}</em></div>`).join('')}</div></section>`:''}`;root.querySelector('#mockAudioTest').onclick=audioTest;root.querySelectorAll('[data-start-exam]').forEach(b=>b.onclick=()=>{const id=b.dataset.startExam;if(confirm(`${examDef(id).title}を開始します。音聲は各題1回のみ、前の問題には戻れません。開始しますか？`))startExam(id)})}
  function renderTransition(root,a){document.body.classList.add('mock-exam-running');cleanupTimers();root.innerHTML=`<div class="mock-exam-shell"><section class="mock-transition-card"><span class="player-kicker">NO BREAK</span><h2>${esc(partLabel(a.nextPart))}</h2><p>${esc(examDef(a.examId).title)}｜次の部へ自動的に進みます。</p><strong id="mockTransitionCount">${Math.max(0,Math.ceil((a.transitionUntil-Date.now())/1000))}</strong></section></div>`;tickTimer=setInterval(()=>tick(root),500)}
  function renderQuestion(root,a){document.body.classList.add('mock-exam-running');cleanupTimers();const QUESTIONS=activeQuestions(a),q=getCurrent(a);if(!q){finishExam('completed');return}const inPart=questionNumberInPart(q,a),partTotal=q.part===3?30:25,selected=a.answers[q.id]||null,played=!!a.played[q.id],isSpeaking=speakingId===q.id,optText=hasTextOptions(q);root.innerHTML=`<div class="mock-exam-shell"><header class="mock-exam-head"><div><span class="player-kicker">${esc(examDef(a.examId).title)}｜${esc(partLabel(q.part))}</span><b>${esc(sectionLabel(q))}</b></div><div class="mock-progress-box"><span>${inPart} / ${partTotal}</span><strong id="mockTimer">${fmtSec(Math.ceil((a.partDeadline-Date.now())/1000))}</strong></div></header><div class="mock-progress-line"><i style="width:${Math.round((inPart-1)/partTotal*100)}%"></i></div><main class="mock-question-card">${q.passage?`<div class="mock-passage">${esc(q.passage).replace(/\n/g,'<br>')}</div>`:''}${renderVisual(q.visual)}${q.prompt?`<h2 class="mock-prompt">${esc(q.prompt)}</h2>`:''}${audioRequired(q)?`<div class="mock-audio-panel"><button class="btn primary mock-audio-btn" id="mockPlayAudio" ${played?'disabled':''}>${isSpeaking?'🔊 再生中…':played?'✓ 音聲は再生済み':'▶ 音聲を1回だけ再生'}</button><span>${played?'この問題の音聲は再生できません。':'再生すると使用済みになります。'}</span></div>`:''}<div class="mock-options ${optText?'with-text':'number-only'}">${q.options.map((o,i)=>`<button class="mock-option ${selected===i+1?'selected':''}" data-mock-answer="${i+1}"><span>${i+1}</span>${optText?`<b>${esc(o)}</b>`:''}</button>`).join('')}</div></main><footer class="mock-exam-foot"><button class="btn danger" id="mockAbort">試驗中止</button><div class="mock-lock-note">← 前の問題には戻れません</div><button class="btn primary" id="mockNext" ${(audioRequired(q)&&(!played||isSpeaking))?'disabled':''}>${a.index===79?'試驗終了':'次の問題 →'}</button></footer></div>`;root.querySelectorAll('[data-mock-answer]').forEach(b=>b.onclick=()=>selectAnswer(q.id,Number(b.dataset.mockAnswer)));const play=root.querySelector('#mockPlayAudio');if(play)play.onclick=()=>playAudio(q);root.querySelector('#mockNext').onclick=nextQuestion;root.querySelector('#mockAbort').onclick=()=>{if(confirm('本回の模擬試驗を中止しますか？現在の解答は成績に残りません。'))abandon()};tickTimer=setInterval(()=>tick(root),500)}
  function renderResults(root,a){document.body.classList.remove('mock-exam-running');cleanupTimers();const r=a.result||{...estimateScore(a),breakdown:scoreBreakdown(a)},target=r.score>=400;root.innerHTML=`<section class="card mock-result-hero"><span class="player-kicker">${esc(examDef(a.examId).title)}｜MOCK SCORE</span><div class="mock-result-score"><strong>${r.score}</strong><span>/ 800</span></div><h2>${esc(r.level||level(r.score))}</h2><div class="mock-target-result ${target?'good':'bad'}">${target?'✓ 400線を超えました':'400線には届きませんでした'}</div><p>IRT-style 模擬尺度分數估計區間：${r.low}–${r.high}。這不是官方 BJT 成績。</p></section><section class="grid mock-result-grid">${[1,2,3].map(p=>{const x=r.breakdown[p];return `<article class="card"><span>${esc(partLabel(p))}</span><strong>${x.correct}/${x.total}</strong><small>${x.accuracy}%</small></article>`}).join('')}<article class="card"><span>總正解</span><strong>${r.correct}/80</strong><small>${Math.round(r.correct/80*100)}%</small></article></section><section class="card mock-score-note"><h3>級別參考區間</h3><div class="mock-level-bands"><span>J5 0–199</span><span>J4 200–319</span><span>J3 320–419</span><span>J2 420–529</span><span>J1 530–599</span><span>J1+ 600–800</span></div><p><b>400分</b>是你的個人目標線；J2參考線為420。</p></section><section class="card"><div class="mock-actions"><button class="btn" id="mockReview">考後詳解を見る</button><button class="btn primary" id="mockDone">模擬試驗首頁へ</button></div><div id="mockReviewArea"></div></section>`;root.querySelector('#mockDone').onclick=()=>{const s=get();s.active=null;save(s);renderIntoCurrent()};root.querySelector('#mockReview').onclick=()=>renderReview(root.querySelector('#mockReviewArea'),a)}
  function renderReview(area,a){const QUESTIONS=activeQuestions(a);area.innerHTML=`<div class="mock-review-list">${QUESTIONS.map((q,idx)=>{const u=a.answers[q.id],ok=u===q.answer;return `<details class="mock-review-item ${ok?'ok':'ng'}"><summary><span>${idx+1}</span><b>${esc(partLabel(q.part))}・${esc(sectionLabel(q))}</b><em>${u==null?'未作答':ok?'○':'×'}</em></summary>${q.passage?`<div class="mock-review-passage">${esc(q.passage).replace(/\n/g,'<br>')}</div>`:''}${audioRequired(q)?`<div class="mock-transcript"><b>考後公開音聲原稿</b><p>${esc(q.audioText||'')}</p></div>`:''}${q.prompt?`<h4>${esc(q.prompt)}</h4>`:''}<ol>${q.options.map((o,i)=>`<li class="${i+1===q.answer?'correct':''} ${i+1===u&&u!==q.answer?'chosen-wrong':''}">${esc(o)}</li>`).join('')}</ol><p><b>正解：</b>${q.answer}　<b>你的答案：</b>${u??'未作答'}</p><p>${esc(q.explanation)}</p></details>`}).join('')}</div>`}
  function render(root){if(!root)return;const s=get(),a=s.active;if(!a){renderHome(root);return}selectedExamId=a.examId||selectedExamId;if(a.status==='finished'||a.phase==='finished'){renderResults(root,a);return}if(a.phase==='transition'){if(Date.now()>=a.transitionUntil){beginPart(a.nextPart);return}renderTransition(root,a);return}if(a.partDeadline&&Date.now()>=a.partDeadline){expirePart();return}renderQuestion(root,a)}
  function renderIntoCurrent(){const root=document.getElementById('view-mockexam');if(root&&root.classList.contains('active'))render(root)}
  function isActive(){const a=get().active;return!!(a&&a.status==='active')} function getActive(){return get().active}
  window.addEventListener('beforeunload',e=>{if(isActive()){e.preventDefault();e.returnValue=''}});
  window.BJT_MOCK_EXAM={render,isActive,getActive,abandon,exams:EXAMS};
})();
